// 8. Verification & Performance Benchmark
// ============================================================================
int main() {
    std::cout << "=== Initializing High-Throughput Wait-Free MVCC In-Memory Storage Engine ===" << std::endl;

    TransactionEngine engine;
    static constexpr size_t NUM_WORKERS = 8;
    static constexpr size_t OPS_PER_WORKER = 50000;
    std::vector<std::thread> workers;

    auto start_time = std::chrono::high_resolution_clock::now();

    for (size_t t = 0; t < NUM_WORKERS; ++t) {
        workers.emplace_back([&engine, t]() {
            size_t tid = EpochManager::Instance().RegisterThread();
            size_t numa = t % MAX_NUMA_NODES;

            for (size_t i = 0; i < OPS_PER_WORKER; ++i) {
                uint64_t key = (i % 1000) + 1; // Skewed Zipfian simulation key space
                auto tx = engine.BeginTransaction(tid, numa);

                if ((i % 10) == 0) {
                    // Read Transaction (10%)
                    uint8_t buffer[32];
                    size_t len = 0;
                    engine.Read(tx, key, buffer, len);
                    engine.Commit(tx);
                } else {
                    // Write Transaction (90%)
                    uint64_t payload_val = 0xDEADBEEF00000000ULL | i;
                    bool ok = engine.Write(tx, key, reinterpret_cast<const uint8_t*>(&payload_val), sizeof(payload_val));
                    if (ok) {
                        engine.Commit(tx);
                    } else {
                        engine.Abort(tx);
                    }
                }
            }
        });
    }

    for (auto& w : workers) {
        w.join();
    }

    auto end_time = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> diff = end_time - start_time;

    double total_ops = NUM_WORKERS * OPS_PER_WORKER;
    std::cout << "Successfully executed " << total_ops << " transactions." << std::endl;
    std::cout << "Elapsed Time: " << diff.count() << " s | Throughput: " 
              << (total_ops / diff.count() / 1e6) << " Mops/sec" << std::endl;

    return 0;
}
