### C++20 Production Implementation

```cpp
#ifndef VBRB_VARIABLE_BOUNDED_RING_BUFFER_HPP
#define VBRB_VARIABLE_BOUNDED_RING_BUFFER_HPP

#include <iostream>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <concepts>
#include <new>
#include <memory>
#include <span>
#include <array>
#include <algorithm>
#include <optional>
#include <thread>
#include <type_traits>

namespace vbrb {

// Fallback for hardware interference size if not defined by the compiler target
#ifdef __cpp_lib_hardware_interference_size
    using std::hardware_destructive_interference_size;
    using std::hardware_constructive_interference_size;
#else
    constexpr size_t hardware_destructive_interference_size = 64;
    constexpr size_t hardware_constructive_interference_size = 64;
#endif

/// @brief Validates that a number is a non-zero power of two.
template <typename T>
    requires std::unsigned_integral<T>
[[nodiscard]] constexpr bool is_power_of_two(T val) noexcept {
    return val != 0 && (val & (val - 1)) == 0;
}

/// @brief Represents a zero-copy 1-part or 2-part memory slice across the ring boundary.
template <typename ByteType>
struct BipartiteSpan {
    std::span<ByteType> first;
    std::span<ByteType> second;

    [[nodiscard]] constexpr size_t total_size() const noexcept {
        return first.size() + second.size();
    }

    [[nodiscard]] constexpr bool is_split() const noexcept {
        return !second.empty();
    }

    /// @brief Scatter-writes source data across the bipartite buffer.
    size_t copy_from(std::span<const std::byte> src) noexcept 
        requires (!std::is_const_v<ByteType>) 
    {
        const size_t to_copy = std::min(total_size(), src.size());
        const size_t first_copy = std::min(first.size(), to_copy);
        const size_t second_copy = to_copy - first_copy;

        if (first_copy > 0) {
            std::copy_n(src.data(), first_copy, first.data());
        }
        if (second_copy > 0) {
            std::copy_n(src.data() + first_copy, second_copy, second.data());
        }
        return to_copy;
    }

    /// @brief Gather-reads bipartite data into a contiguous destination buffer.
    size_t copy_to(std::span<std::byte> dst) const noexcept {
        const size_t to_copy = std::min(total_size(), dst.size());
        const size_t first_copy = std::min(first.size(), to_copy);
        const size_t second_copy = to_copy - first_copy;

        if (first_copy > 0) {
            std::copy_n(first.data(), first_copy, dst.data());
        }
        if (second_copy > 0) {
            std::copy_n(second.data(), second_copy, dst.data() + first_copy);
        }
        return to_copy;
    }
};

using MutableBipartiteSpan = BipartiteSpan<std::byte>;
using ConstBipartiteSpan = BipartiteSpan<const std::byte>;

/// @brief Epoch-Based Reclamation (EBR) Manager for safe concurrent variable-length reading.
template <size_t MaxReaders = 128>
class EpochManager {
public:
    static constexpr uint64_t INACTIVE_EPOCH = std::numeric_limits<uint64_t>::max();

    struct alignas(hardware_destructive_interference_size) ReaderSlot {
        std::atomic<uint64_t> active_epoch{INACTIVE_EPOCH};
        std::atomic<bool> is_registered{false};
    };

    EpochManager() noexcept {
        global_epoch_.store(0, std::memory_order_relaxed);
        for (auto& slot : reader_slots_) {
            slot.active_epoch.store(INACTIVE_EPOCH, std::memory_order_relaxed);
            slot.is_registered.store(false, std::memory_order_relaxed);
        }
    }

    /// @brief Registers a thread for epoch-based reading.
    [[nodiscard]] size_t register_reader() noexcept {
        for (size_t i = 0; i < MaxReaders; ++i) {
            bool expected = false;
            if (reader_slots_[i].is_registered.compare_exchange_strong(
                    expected, true, std::memory_order_acq_rel, std::memory_order_relaxed)) {
                return i;
            }
        }
        return std::numeric_limits<size_t>::max();
    }

    /// @brief Unregisters a thread.
    void unregister_reader(size_t slot_idx) noexcept {
        if (slot_idx < MaxReaders) {
            reader_slots_[slot_idx].active_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
            reader_slots_[slot_idx].is_registered.store(false, std::memory_order_release);
        }
    }

    /// @brief Reader pins the current global epoch before dereferencing memory slices.
    void enter_epoch(size_t slot_idx, uint64_t current_read_offset) noexcept {
        if (slot_idx < MaxReaders) {
            reader_slots_[slot_idx].active_epoch.store(current_read_offset, std::memory_order_release);
            // Asymmetric thread fence to enforce visibility on weak memory architectures
            std::atomic_thread_fence(std::memory_order_seq_cst);
        }
    }

    /// @brief Reader unpins the active epoch after completing slice consumption.
    void exit_epoch(size_t slot_idx) noexcept {
        if (slot_idx < MaxReaders) {
            reader_slots_[slot_idx].active_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
        }
    }

    /// @brief Computes the oldest pinned read-offset across all active readers.
    [[nodiscard]] uint64_t get_oldest_active_epoch(uint64_t current_tail) const noexcept {
        uint64_t oldest = current_tail;
        for (size_t i = 0; i < MaxReaders; ++i) {
            if (reader_slots_[i].is_registered.load(std::memory_order_acquire)) {
                const uint64_t epoch = reader_slots_[i].active_epoch.load(std::memory_order_acquire);
                if (epoch != INACTIVE_EPOCH) {
                    oldest = std::min(oldest, epoch);
                }
            }
        }
        return oldest;
    }

private:
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_{0};
    std::array<ReaderSlot, MaxReaders> reader_slots_;
};

/// @brief Variable-Length Bounded Ring Buffer supporting MPMC batch commits, 
/// zero-copy wrap-around slicing, and epoch-based hazard safety.
template <size_t CapacityBytes, size_t MaxPendingTickets = 65536, size_t MaxReaders = 128>
class VariableBoundedRingBuffer {
    static_assert(is_power_of_two(CapacityBytes), "CapacityBytes must be a power of 2.");
    static_assert(is_power_of_two(MaxPendingTickets), "MaxPendingTickets must be a power of 2.");

public:
    static constexpr size_t BUFFER_CAPACITY = CapacityBytes;
    static constexpr size_t BUFFER_MASK = CapacityBytes - 1;
    static constexpr size_t TICKET_MASK = MaxPendingTickets - 1;

    struct ReservationDescriptor {
        MutableBipartiteSpan slice;
        uint64_t ticket{0};
        uint64_t start_offset{0};
        uint64_t end_offset{0};
        bool valid{false};
    };

    struct ReadBatchDescriptor {
        ConstBipartiteSpan slice;
        uint64_t start_offset{0};
        uint64_t end_offset{0};
        size_t reader_slot{std::numeric_limits<size_t>::max()};
        bool valid{false};
    };

    VariableBoundedRingBuffer() 
        : raw_buffer_(std::make_unique<std::byte[]>(CapacityBytes))
    {
        reserved_write_head_.store(0, std::memory_order_relaxed);
        published_write_tail_.store(0, std::memory_order_relaxed);
        read_head_.store(0, std::memory_order_relaxed);
        reclaimed_tail_.store(0, std::memory_order_relaxed);
        ticket_generator_.store(0, std::memory_order_relaxed);
        commit_barrier_ticket_.store(0, std::memory_order_relaxed);

        for (size_t i = 0; i < MaxPendingTickets; ++i) {
            commit_table_[i].ticket.store(std::numeric_limits<uint64_t>::max(), std::memory_order_relaxed);
            commit_table_[i].end_offset.store(0, std::memory_order_relaxed);
        }
    }

    ~VariableBoundedRingBuffer() = default;
    VariableBoundedRingBuffer(const VariableBoundedRingBuffer&) = delete;
    VariableBoundedRingBuffer& operator=(const VariableBoundedRingBuffer&) = delete;
    VariableBoundedRingBuffer(VariableBoundedRingBuffer&&) = delete;
    VariableBoundedRingBuffer& operator=(VariableBoundedRingBuffer&&) = delete;

    // --- Epoch Management Proxy ---
    [[nodiscard]] size_t register_reader() noexcept {
        return epoch_manager_.register_reader();
    }

    void unregister_reader(size_t reader_slot) noexcept {
        epoch_manager_.unregister_reader(reader_slot);
    }

    // =========================================================================
    // PRODUCER API (Two-Phase Commit Protocol)
    // =========================================================================

    /// @brief Phase 1: Atomically reserves a variable-length byte range.
    [[nodiscard]] std::optional<ReservationDescriptor> reserve(size_t len) noexcept {
        if (len == 0 || len > BUFFER_CAPACITY) {
            return std::nullopt;
        }

        uint64_t curr_reserved = reserved_write_head_.load(std::memory_order_relaxed);

        while (true) {
            const uint64_t tail = reclaimed_tail_.load(std::memory_order_acquire);
            const uint64_t safe_tail = epoch_manager_.get_oldest_active_epoch(tail);

            // Buffer full check: ensure we do not overwrite unconsumed/pinned data
            if ((curr_reserved + len) - safe_tail > BUFFER_CAPACITY) {
                return std::nullopt; // Backpressure / Full
            }

            if (reserved_write_head_.compare_exchange_weak(
                    curr_reserved, curr_reserved + len,
                    std::memory_order_acq_rel, std::memory_order_relaxed)) {
                break;
            }
            // curr_reserved updated automatically on CAS failure
        }

        const uint64_t start_offset = curr_reserved;
        const uint64_t end_offset = curr_reserved + len;
        const uint64_t ticket = ticket_generator_.fetch_add(1, std::memory_order_relaxed);

        // Compute Bipartite Spans across the wrap-around boundary
        const size_t physical_start = static_cast<size_t>(start_offset & BUFFER_MASK);
        const size_t contiguous_to_end = BUFFER_CAPACITY - physical_start;

        MutableBipartiteSpan span;
        if (len <= contiguous_to_end) {
            span.first = std::span<std::byte>(raw_buffer_.get() + physical_start, len);
            span.second = std::span<std::byte>{};
        } else {
            span.first = std::span<std::byte>(raw_buffer_.get() + physical_start, contiguous_to_end);
            span.second = std::span<std::byte>(raw_buffer_.get(), len - contiguous_to_end);
        }

        return ReservationDescriptor{
            .slice = span,
            .ticket = ticket,
            .start_offset = start_offset,
            .end_offset = end_offset,
            .valid = true
        };
    }

    /// @brief Phase 2: Commits a previously reserved slot, advancing the readable tail.
    void commit(const ReservationDescriptor& desc) noexcept {
        if (!desc.valid) return;

        const size_t slot = static_cast<size_t>(desc.ticket & TICKET_MASK);

        // Record metadata before publishing the ticket
        commit_table_[slot].end_offset.store(desc.end_offset, std::memory_order_relaxed);
        commit_table_[slot].ticket.store(desc.ticket, std::memory_order_release);

        // Asynchronously advance the published tail (sweeps in-order commits)
        advance_published_tail();
    }

    // =========================================================================
    // CONSUMER API (Batch Slicing & Epoch-Protected Leases)
    // =========================================================================

    /// @brief Acquires a zero-copy batch of up to `max_len` bytes.
    [[nodiscard]] std::optional<ReadBatchDescriptor> acquire_read_batch(
        size_t reader_slot, size_t max_len = BUFFER_CAPACITY) noexcept 
    {
        if (max_len == 0) return std::nullopt;

        uint64_t curr_read = read_head_.load(std::memory_order_relaxed);

        while (true) {
            // Pin epoch to current read position to guard against producer wraparound
            epoch_manager_.enter_epoch(reader_slot, curr_read);

            const uint64_t published = published_write_tail_.load(std::memory_order_acquire);
            if (curr_read >= published) {
                epoch_manager_.exit_epoch(reader_slot);
                return std::nullopt; // Nothing to read
            }

            const size_t available = static_cast<size_t>(published - curr_read);
            const size_t to_read = std::min(available, max_len);
            const uint64_t target_read = curr_read + to_read;

            if (read_head_.compare_exchange_weak(
                    curr_read, target_read,
                    std::memory_order_acq_rel, std::memory_order_relaxed)) {

                const size_t physical_start = static_cast<size_t>(curr_read & BUFFER_MASK);
                const size_t contiguous_to_end = BUFFER_CAPACITY - physical_start;

                ConstBipartiteSpan span;
                if (to_read <= contiguous_to_end) {
                    span.first = std::span<const std::byte>(raw_buffer_.get() + physical_start, to_read);
                    span.second = std::span<const std::byte>{};
                } else {
                    span.first = std::span<const std::byte>(raw_buffer_.get() + physical_start, contiguous_to_end);
                    span.second = std::span<const std::byte>(raw_buffer_.get(), to_read - contiguous_to_end);
                }

                return ReadBatchDescriptor{
                    .slice = span,
                    .start_offset = curr_read,
                    .end_offset = target_read,
                    .reader_slot = reader_slot,
                    .valid = true
                };
            }
            // CAS failed: retry with updated curr_read
        }
    }

    /// @brief Releases the read lease, retiring the epoch pin and advancing reclamation.
    void release_read_batch(ReadBatchDescriptor& desc) noexcept {
        if (!desc.valid) return;

        // Advance reclaimed tail monotonically
        uint64_t curr_reclaimed = reclaimed_tail_.load(std::memory_order_relaxed);
        while (desc.end_offset > curr_reclaimed) {
            if (reclaimed_tail_.compare_exchange_weak(
                    curr_reclaimed, desc.end_offset,
                    std::memory_order_release, std::memory_order_relaxed)) {
                break;
            }
        }

        epoch_manager_.exit_epoch(desc.reader_slot);
        desc.valid = false;
    }

private:
    /// @brief Sweeps contiguous committed tickets forward to update `published_write_tail_`.
    void advance_published_tail() noexcept {
        while (true) {
            uint64_t expected_ticket = commit_barrier_ticket_.load(std::memory_order_acquire);
            const size_t slot = static_cast<size_t>(expected_ticket & TICKET_MASK);

            if (commit_table_[slot].ticket.load(std::memory_order_acquire) != expected_ticket) {
                break; // Earliest uncommitted producer still in-flight
            }

            const uint64_t end_offset = commit_table_[slot].end_offset.load(std::memory_order_relaxed);

            if (commit_barrier_ticket_.compare_exchange_strong(
                    expected_ticket, expected_ticket + 1,
                    std::memory_order_acq_rel, std::memory_order_relaxed)) {

                // Advance global published tail
                uint64_t curr_pub = published_write_tail_.load(std::memory_order_relaxed);
                while (end_offset > curr_pub) {
                    if (published_write_tail_.compare_exchange_weak(
                            curr_pub, end_offset,
                            std::memory_order_release, std::memory_order_relaxed)) {
                        break;
                    }
                }

                // Clear the slot for wrap-around reuse
                commit_table_[slot].ticket.store(std::numeric_limits<uint64_t>::max(), std::memory_order_release);
            }
        }
    }

private:
    struct CommitEntry {
        std::atomic<uint64_t> ticket{std::numeric_limits<uint64_t>::max()};
        std::atomic<uint64_t> end_offset{0};
    };

    // Primary Data Storage
    std::unique_ptr<std::byte[]> raw_buffer_;

    // Isolated Cache-Line Atomic Cursors (False Sharing Elimination)
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> reserved_write_head_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> published_write_tail_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> read_head_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> reclaimed_tail_{0};

    // Ticket & Commit Synchronization
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> ticket_generator_{0};
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> commit_barrier_ticket_{0};

    alignas(hardware_destructive_interference_size) 
    std::array<CommitEntry, MaxPendingTickets> commit_table_;

    // Epoch Garbage Collector
    alignas(hardware_destructive_interference_size) 
    EpochManager<MaxReaders> epoch_manager_;
};

} // namespace vbrb

#endif // VBRB_VARIABLE_BOUNDED_RING_BUFFER_HPP
```

---

### Formal Concurrency & Edge-Case Verification

#### 1. Formal Memory Ordering & Synchronization Proof
The synchronization edge between concurrent producers and reading consumers is established without `std::memory_order_seq_cst`:

```
PRODUCER THREAD                                        CONSUMER THREAD
═══════════════                                        ═══════════════
Write payload data into std::span<std::byte>
       │
       ▼ (Sequenced-before)
commit_table_[slot].ticket.store(ticket, release)
       │
       ▼ (Synchronizes-with via acquire loop)
advance_published_tail():
  commit_barrier_ticket_.compare_exchange_strong(acq_rel)
  published_write_tail_.store(end_offset, release)
       │
       └───────────────────────────────────────────────► published_write_tail_.load(acquire)
                                                               │
                                                               ▼ (Happens-before)
                                                         Read payload data from std::span<const std::byte>
```

- **Theorem 1 (Payload Data Integrity):** A consumer reading payload data at offset $K$ will never observe uninitialized memory or out-of-order writes.
  - *Proof:* Producer writes payload into `raw_buffer_` sequenced-before `commit_table_.ticket.store(..., release)`. The sweep worker acquires this store, synchronizing with the producer. The subsequent `published_write_tail_.store(..., release)` synchronizes-with `published_write_tail_.load(..., acquire)` in `acquire_read_batch()`. By transitivity of the *happens-before* relation, the write of the payload data happens-before the consumer accesses the bipartite span.

#### 2. ABA Mitigation Over 64-Bit Monotonic Sequence Space
- Monotonic sequence counters (`reserved_write_head_`, `read_head_`, `ticket_generator_`) increment continuously as $64$-bit unsigned integers without wrapping modulo capacity in logic.
- At an ingress throughput of $100\text{ million messages/sec}$ of $256\text{ bytes each}$ ($25.6\text{ GB/sec}$), wrapping a $2^{64}$ counter requires:
  $$\frac{2^{64}\text{ bytes}}{25.6 \times 10^9\text{ bytes/sec}} \approx 7.2 \times 10^8\text{ seconds} \approx 22.8\text{ years}$$
- Consequently, ABA state confusion on CAS operations is mathematically eliminated across the operating lifespan of the process.

#### 3. Deadlock / Livelock Avoidance under Producer Stalls
- **Scenario:** Producer $A$ reserves $[0, 128)$ (Ticket 0) and Producer $B$ reserves $[128, 256)$ (Ticket 1). Producer $A$ is preempted/descheduled by the OS before calling `commit()`.
- **Handling:** Producer $B$ completes its write and atomically marks Ticket 1 as complete in `commit_table_[1]`. Producer $B$'s call to `advance_published_tail()` observes that `commit_barrier_ticket_` (0) is uncommitted and cleanly returns without blocking.
- No mutexes or spinlocks are held. When Producer $A$ awakens and commits Ticket 0, `advance_published_tail()` sweeps forward through **both** Ticket 0 and Ticket 1 in a single linear pass, immediately advancing `published_write_tail_` to 256.

#### 4. Power-of-Two Split Boundary Pointer Arithmetic
Given Capacity $N = 2^k$ and Mask $M = N - 1$:
- For any monotonic offset $S$ and reservation length $L$:
  $$\text{Physical Index} = S \ \& \ M$$
  $$\text{Contiguous Distance to End} = N - (S \ \& \ M)$$
- **Case 1 ($L \le N - (S \ \& \ M)$):** The payload fits entirely within the contiguous suffix of the buffer.
  $$\text{Span}_1 = [\text{buffer} + (S \ \& \ M), \ L), \quad \text{Span}_2 = \emptyset$$
- **Case 2 ($L > N - (S \ \& \ M)$):** The payload wraps across the circular boundary.
  $$\text{Span}_1 = [\text{buffer} + (S \ \& \ M), \ N - (S \ \& \ M)), \quad \text{Span}_2 = [\text{buffer}, \ L - (N - (S \ \& \ M)))$$
- Index masking via bitwise AND ($S \ \& \ M$) evaluates in a single CPU clock cycle, avoiding costly integer division (`idiv`).

---

### Complexity & Spatial Overhead Analysis

| Operation | Amortized Time | Worst-Case Time | Contention Behavior |
| :--- | :--- | :--- | :--- |
| **`reserve(len)`** | $\mathcal{O}(1)$ | $\mathcal{O}(R)$ ($R = \text{active readers}$) | Lock-Free CAS on `reserved_write_head_` |
| **`commit(desc)`** | $\mathcal{O}(1)$ | $\mathcal{O}(T)$ ($T = \text{pending tickets}$) | Wait-Free slot store + sweep |
| **`acquire_read_batch()`** | $\mathcal{O}(1)$ | $\mathcal{O}(1)$ | Lock-Free CAS on `read_head_` |
| **`release_read_batch()`** | $\mathcal{O}(1)$ | $\mathcal{O}(1)$ | Lock-Free CAS on `reclaimed_tail_` |

#### Spatial Memory Overhead
- **Data Buffer:** Exactly $N$ bytes (contiguous, zero allocation).
- **Coordination Metadata:**
  $$\text{Overhead} = 6 \times \text{CacheLine} + (\text{MaxPendingTickets} \times 16\text{ bytes}) + (\text{MaxReaders} \times 64\text{ bytes})$$
  For $N = 64\text{ MB}$, $\text{MaxPendingTickets} = 65,536$, and $\text{MaxReaders} = 128$:
  $$\text{Overhead} = 384\text{ B} + 1,048,576\text{ B} + 8,192\text{ B} \approx 1.05\text{ MB} \quad (\approx 1.6\%\text{ of buffer capacity})$$
- **Per-Reserved-Byte Heap Allocations:** Exactly $0$ bytes.

