#include <array>
#include <optional>
#include <chrono>
#include <new>

namespace mvcc {

// ----------------------------------------------------------------------------
// Constants & Configuration
// ----------------------------------------------------------------------------
inline constexpr uint64_t INF_TS = UINT64_MAX;
inline constexpr uint64_t TOMBSTONE_BIT = (1ULL << 63);
inline constexpr size_t CACHE_LINE_SIZE = 64;
inline constexpr size_t NUM_EPOCHS = 3;
inline constexpr size_t MAX_THREADS = 256;
inline constexpr size_t ARENA_BLOCK_SIZE = 4 * 1024 * 1024; // 4MB Chunk

// ----------------------------------------------------------------------------
// Tuple Version Record Structure (64-byte Cache-line Aligned)
// ----------------------------------------------------------------------------
struct alignas(CACHE_LINE_SIZE) VersionRecord {
    std::atomic<uint64_t> begin_ts{INF_TS};
    std::atomic<uint64_t> end_ts{INF_TS};
    std::atomic<uint64_t> tx_id{0};
    std::atomic<VersionRecord*> prev{nullptr};

    uint64_t key{0};
    uint32_t val_size{0};
    bool is_tombstone{false};
    char inline_payload[24]; // Small strings stored inline to eliminate dereferences
    char* dynamic_payload{nullptr};

    [[nodiscard]] std::string_view get_value() const noexcept {
        if (is_tombstone) return {};
        if (val_size <= sizeof(inline_payload)) {
            return std::string_view(inline_payload, val_size);
        }
        return std::string_view(dynamic_payload, val_size);
    }

    void set_value(std::string_view sv) {
        val_size = static_cast<uint32_t>(sv.size());
        is_tombstone = false;
        if (val_size <= sizeof(inline_payload)) {
            if (val_size > 0) {
                std::memcpy(inline_payload, sv.data(), val_size);
            }
            dynamic_payload = nullptr;
        } else {
            dynamic_payload = new char[val_size];
            std::memcpy(dynamic_payload, sv.data(), val_size);
        }
    }

    ~VersionRecord() {
        if (val_size > sizeof(inline_payload) && dynamic_payload != nullptr) {
            delete[] dynamic_payload;
            dynamic_payload = nullptr;
        }
    }
};
static_assert(sizeof(VersionRecord) % CACHE_LINE_SIZE == 0, "VersionRecord must be cache-line aligned");

// ----------------------------------------------------------------------------
// Lock-Free 3-Epoch Memory Reclamation (EBR)
// ----------------------------------------------------------------------------
class EBRManager {
public:
    struct alignas(CACHE_LINE_SIZE) ThreadControlBlock {
        std::atomic<bool> active{false};
        std::atomic<uint64_t> local_epoch{0};
        std::atomic<uint64_t> active_snapshot_ts{INF_TS};

        // Limbo bags for deferred reclamation across 3 epochs
        std::vector<VersionRecord*> limbo_bags[NUM_EPOCHS];
        size_t retired_count{0};
    };

    static EBRManager& instance() {
        static EBRManager instance;
        return instance;
    }

    size_t register_thread() {
        size_t id = next_thread_id_.fetch_add(1, std::memory_order_relaxed);
        if (id >= MAX_THREADS) {
            throw std::runtime_error("Maximum thread limit exceeded in EBRManager");
        }
        tcbs_[id] = std::make_unique<ThreadControlBlock>();
        return id;
    }

    inline void enter_critical(size_t tid, uint64_t snapshot_ts) noexcept {
        auto& tcb = *tcbs_[tid];
        tcb.active_snapshot_ts.store(snapshot_ts, std::memory_order_relaxed);
        uint64_t global_e = global_epoch_.load(std::memory_order_relaxed);
        tcb.local_epoch.store(global_e, std::memory_order_relaxed);
        tcb.active.store(true, std::memory_order_seq_cst);
    }

    inline void exit_critical(size_t tid) noexcept {
        auto& tcb = *tcbs_[tid];
        tcb.active.store(false, std::memory_order_seq_cst);
        tcb.active_snapshot_ts.store(INF_TS, std::memory_order_relaxed);
    }

    void retire(size_t tid, VersionRecord* rec) {
        auto& tcb = *tcbs_[tid];
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        tcb.limbo_bags[cur_epoch % NUM_EPOCHS].push_back(rec);
        tcb.retired_count++;

        if (tcb.retired_count >= 64) {
            try_advance_and_reclaim(tid);
            tcb.retired_count = 0;
        }
    }

    void try_advance_and_reclaim(size_t tid) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t thread_count = next_thread_id_.load(std::memory_order_relaxed);

        // Check if all active threads have witnessed the current epoch
        for (size_t i = 0; i < thread_count; ++i) {
            if (tcbs_[i] && tcbs_[i]->active.load(std::memory_order_acquire)) {
                if (tcbs_[i]->local_epoch.load(std::memory_order_relaxed) != cur_epoch) {
                    return; // Stale thread present; cannot advance global epoch
                }
            }
        }

        // Advance global epoch
        uint64_t next_epoch = cur_epoch + 1;
        if (global_epoch_.compare_exchange_strong(cur_epoch, next_epoch, std::memory_order_acq_rel)) {
            // Safe to reclaim memory from epoch (next_epoch + 1) % 3 == (next_epoch - 2) % 3
            size_t reclaim_idx = (next_epoch + 1) % NUM_EPOCHS;
            auto& tcb = *tcbs_[tid];
            for (auto* rec : tcb.limbo_bags[reclaim_idx]) {
                delete rec;
            }
            tcb.limbo_bags[reclaim_idx].clear();
        }
    }

    uint64_t get_min_active_snapshot() const noexcept {
        uint64_t min_ts = INF_TS;
        size_t thread_count = next_thread_id_.load(std::memory_order_relaxed);
        for (size_t i = 0; i < thread_count; ++i) {
            if (tcbs_[i] && tcbs_[i]->active.load(std::memory_order_acquire)) {
                uint64_t ts = tcbs_[i]->active_snapshot_ts.load(std::memory_order_relaxed);
                if (ts < min_ts) {
                    min_ts = ts;
                }
            }
        }
        return min_ts;
    }

private:
    EBRManager() : global_epoch_(0), next_thread_id_(0) {}

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_epoch_{0};
    alignas(CACHE_LINE_SIZE) std::atomic<size_t> next_thread_id_{0};
    std::array<std::unique_ptr<ThreadControlBlock>, MAX_THREADS> tcbs_;
};

// ----------------------------------------------------------------------------
// Thread-Local Context
// ----------------------------------------------------------------------------
struct ThreadContext {
    size_t tid{0};
    bool registered{false};

    void ensure_registered() {
        if (!registered) {
            tid = EBRManager::instance().register_thread();
            registered = true;
        }
    }
};

inline thread_local ThreadContext tl_context;

// ----------------------------------------------------------------------------
// High-Concurrency Lock-Free Index (Atomic Split-Bucketed Masstree Map)
// ----------------------------------------------------------------------------
class PrimaryIndex {
private:
    static constexpr size_t NUM_BUCKETS = 65536; // 64K Partitioned striped buckets

    struct Bucket {
        alignas(CACHE_LINE_SIZE) std::atomic<VersionRecord*> head{nullptr};
        alignas(CACHE_LINE_SIZE) std::mutex latch; // Fine-grained bucket latch for OCC inserts
    };

    std::vector<Bucket> buckets_;

    [[nodiscard]] inline size_t hash_key(uint64_t key) const noexcept {
        // High-avalanche Murmur3 finalizer
        key ^= key >> 33;
        key *= 0xff51afd7ed558ccdULL;
        key ^= key >> 33;
        key *= 0xc4ceb9fe1a85ec53ULL;
        key ^= key >> 33;
        return key % NUM_BUCKETS;
    }

public:
    PrimaryIndex() : buckets_(NUM_BUCKETS) {}

    [[nodiscard]] inline VersionRecord* get_chain_head(uint64_t key) const noexcept {
        size_t b_idx = hash_key(key);
        // Lock-free atomic load with acquire barrier
        return buckets_[b_idx].head.load(std::memory_order_acquire);
    }

    inline bool cas_chain_head(uint64_t key, VersionRecord* expected, VersionRecord* desired) noexcept {
        size_t b_idx = hash_key(key);
        return buckets_[b_idx].head.compare_exchange_strong(
            expected, desired, std::memory_order_acq_rel, std::memory_order_acquire);
    }

    inline void lock_bucket(uint64_t key) {
        buckets_[hash_key(key)].latch.lock();
    }

    inline void unlock_bucket(uint64_t key) {
        buckets_[hash_key(key)].latch.unlock();
    }
};

// ----------------------------------------------------------------------------
// Transaction Context & Local Buffers
// ----------------------------------------------------------------------------
enum class TxStatus { ACTIVE, COMMITTED, ABORTED };

struct WriteOp {
    uint64_t key;
    std::string value;
    bool is_remove;
    VersionRecord* new_version_ptr{nullptr};
    VersionRecord* locked_head{nullptr};
};

class Transaction {
public:
    uint64_t tx_id;
    uint64_t read_ts;
    uint64_t commit_ts{0};
    TxStatus status{TxStatus::ACTIVE};
    std::vector<WriteOp> write_set;

    Transaction(uint64_t id, uint64_t r_ts) : tx_id(id), read_ts(r_ts) {}
};

// ----------------------------------------------------------------------------
// MVCC Storage Engine Implementation
// ----------------------------------------------------------------------------
class MVCCStorageEngine {
public:
    MVCCStorageEngine() 
        : global_clock_(1), next_tx_id_(100) {}

    ~MVCCStorageEngine() = default;

    Transaction begin_transaction() {
        tl_context.ensure_registered();

        // Allocate monotonically increasing snapshot read timestamp
        uint64_t r_ts = global_clock_.load(std::memory_order_relaxed);
        uint64_t t_id = next_tx_id_.fetch_add(1, std::memory_order_relaxed);

        // Enter EBR critical section
        EBRManager::instance().enter_critical(tl_context.tid, r_ts);

        return Transaction(t_id, r_ts);
    }

    // ------------------------------------------------------------------------
    // Wait-Free Point Lookup (SI Read)
    // ------------------------------------------------------------------------
    bool get(Transaction& tx, uint64_t key, std::string& out_value) {
        // 1. Check local write-set for read-your-own-writes consistency
        for (auto it = tx.write_set.rbegin(); it != tx.write_set.rend(); ++it) {
            if (it->key == key) {
                if (it->is_remove) {
                    return false;
                }
                out_value = it->value;
                return true;
            }
        }

        // 2. Lock-free Version Chain Traversal (N2O)
        VersionRecord* curr = index_.get_chain_head(key);
        while (curr != nullptr) {
            // Synchronize with version publishing
            uint64_t b_ts = curr->begin_ts.load(std::memory_order_acquire);
            uint64_t e_ts = curr->end_ts.load(std::memory_order_acquire);
            uint64_t v_tx_id = curr->tx_id.load(std::memory_order_acquire);

            // Visibility criteria:
            // 1. Version must be committed with begin_ts <= tx.read_ts OR created by self
            // 2. Version must not be superseded (read_ts < end_ts)
            if ((b_ts <= tx.read_ts || v_tx_id == tx.tx_id) && (tx.read_ts < e_ts)) {
                if (curr->is_tombstone) {
                    return false; // Key deleted
                }
                if (curr->key == key) {
                    out_value = std::string(curr->get_value());
                    return true;
                }
            }

            // Move backward in time
            curr = curr->prev.load(std::memory_order_acquire);
        }

        return false;
    }

    bool put(Transaction& tx, uint64_t key, std::string_view value) {
        if (tx.status != TxStatus::ACTIVE) return false;

        // Buffer into thread-local write set
        tx.write_set.push_back(WriteOp{
            .key = key,
            .value = std::string(value),
            .is_remove = false,
            .new_version_ptr = nullptr,
            .locked_head = nullptr
        });
        return true;
    }

    bool remove(Transaction& tx, uint64_t key) {
        if (tx.status != TxStatus::ACTIVE) return false;

        tx.write_set.push_back(WriteOp{
            .key = key,
            .value = "",
            .is_remove = true,
            .new_version_ptr = nullptr,
            .locked_head = nullptr
        });
        return true;
    }

    // ------------------------------------------------------------------------
    // Decentralized OCC Commit Protocol (Two-Phase Validation)
    // ------------------------------------------------------------------------
    bool commit(Transaction& tx) {
        if (tx.status != TxStatus::ACTIVE) return false;

        // Read-only transactions commit trivially
        if (tx.write_set.empty()) {
            tx.status = TxStatus::COMMITTED;
            EBRManager::instance().exit_critical(tl_context.tid);
            return true;
        }

        // Deduplicate write-set by keeping latest op per key
        std::vector<WriteOp> unique_writes;
        for (auto& op : tx.write_set) {
            bool found = false;
            for (auto& u : unique_writes) {
                if (u.key == op.key) {
                    u = op;
                    found = true;
                    break;
                }
            }
            if (!found) {
                unique_writes.push_back(op);
            }
        }

        // Sort keys to prevent deadlocks during multi-latching
        std::sort(unique_writes.begin(), unique_writes.end(), 
                  [](const WriteOp& a, const WriteOp& b) { return a.key < b.key; });

        // Phase 1: Lock Write-Set & First-Committer-Wins Validation
        std::vector<size_t> locked_indices;
        bool validation_success = true;

        for (size_t i = 0; i < unique_writes.size(); ++i) {
            auto& op = unique_writes[i];
            index_.lock_bucket(op.key);
            locked_indices.push_back(i);

            VersionRecord* head = index_.get_chain_head(op.key);
            op.locked_head = head;

            if (head != nullptr) {
                uint64_t head_b_ts = head->begin_ts.load(std::memory_order_acquire);
                uint64_t head_tx_id = head->tx_id.load(std::memory_order_acquire);

                // Check for concurrent active writer or subsequent committed version
                if ((head_tx_id != 0 && head_tx_id != tx.tx_id) || (head_b_ts > tx.read_ts)) {
                    validation_success = false;
                    break;
                }
            }
        }

        if (!validation_success) {
            // Unlock all held latches and abort
            for (size_t idx : locked_indices) {
                index_.unlock_bucket(unique_writes[idx].key);
            }
            abort(tx);
            return false;
        }

        // Phase 2: Allocate Atomic Commit Timestamp
        uint64_t c_ts = global_clock_.fetch_add(1, std::memory_order_acq_rel) + 1;
        tx.commit_ts = c_ts;

        // Phase 3: Create and Prepend New Versions
        for (auto& op : unique_writes) {
            auto* new_rec = new VersionRecord();
            new_rec->key = op.key;
            new_rec->begin_ts.store(c_ts, std::memory_order_relaxed);
            new_rec->end_ts.store(INF_TS, std::memory_order_relaxed);
            new_rec->tx_id.store(0, std::memory_order_relaxed);
            new_rec->prev.store(op.locked_head, std::memory_order_relaxed);

            if (op.is_remove) {
                new_rec->is_tombstone = true;
            } else {
                new_rec->set_value(op.value);
            }

            op.new_version_ptr = new_rec;
        }

        // Phase 4: Atomic Publish & Link Head
        for (auto& op : unique_writes) {
            if (op.locked_head != nullptr) {
                // Invalidate superseded version
                op.locked_head->end_ts.store(c_ts, std::memory_order_release);
            }
            // Swap head to new record with release semantics
            index_.cas_chain_head(op.key, op.locked_head, op.new_version_ptr);
        }

        // Phase 5: Unlock Latches & Register Superseded Records into EBR
        for (size_t idx : locked_indices) {
            auto& op = unique_writes[idx];
            index_.unlock_bucket(op.key);
            if (op.locked_head != nullptr) {
                EBRManager::instance().retire(tl_context.tid, op.locked_head);
            }
        }

        tx.status = TxStatus::COMMITTED;
        EBRManager::instance().exit_critical(tl_context.tid);
        return true;
    }

    void abort(Transaction& tx) {
        tx.status = TxStatus::ABORTED;
        tx.write_set.clear();
        EBRManager::instance().exit_critical(tl_context.tid);
    }

    // ------------------------------------------------------------------------
    // Engine Maintenance & Garbage Collection
    // ------------------------------------------------------------------------
    void run_maintenance_cycle() {
        tl_context.ensure_registered();
        EBRManager::instance().try_advance_and_reclaim(tl_context.tid);
    }

private:
    PrimaryIndex index_;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_clock_;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> next_tx_id_;
};

} // namespace mvcc
