## Part 3: Concurrent Stress Test & Benchmark Suite

The benchmarking suite below evaluates:
1. **90% Read / 10% Write** Workload with high-skew **Zipfian Key Distribution** ($\theta = 0.99$).
2. **50% Read / 50% Write** High-Contention Workload.
3. Strict Snapshot Isolation validation checks (detecting lost updates and phantom reads).
4. Tail Latency metrics ($p50$, $p90$, $p99$, $p99.9$) and Throughput (Million Operations/sec).

```cpp
// ============================================================================
// File: benchmark_main.cpp
// Description: Multi-Threaded Stress Test and Skewed Workload Benchmark
// ============================================================================

#include "mvcc_engine.hpp"
#include <random>
#include <chrono>
#include <vector>
#include <thread>
#include <algorithm>
#include <iomanip>
#include <cmath>

// ----------------------------------------------------------------------------
// Zipfian Generator (Rejection-Inversion Method)
// ----------------------------------------------------------------------------
class ZipfianGenerator {
public:
    ZipfianGenerator(uint64_t n, double theta) 
        : n_(n), theta_(theta), alpha_(1.0 / (1.0 - theta)), zetan_(zeta(n, theta)) {
        eta_ = (1.0 - std::pow(2.0 / static_cast<double>(n_), 1.0 - theta)) / 
               (1.0 - zeta(2, theta) / zetan_);
    }

    uint64_t next(std::mt19937_64& rng) {
        std::uniform_real_distribution<double> dist(0.0, 1.0);
        double u = dist(rng);
        double uz = u * zetan_;
        if (uz < 1.0) return 0;
        if (uz < 1.0 + std::pow(0.5, theta_)) return 1;
        return static_cast<uint64_t>(static_cast<double>(n_) * std::pow(eta_ * u - eta_ + 1.0, alpha_));
    }

private:
    static double zeta(uint64_t n, double theta) {
        double sum = 0;
        for (uint64_t i = 1; i <= n; ++i) {
            sum += 1.0 / std::pow(static_cast<double>(i), theta);
        }
        return sum;
    }

    uint64_t n_;
    double theta_;
    double alpha_;
    double zetan_;
    double eta_;
};

// ----------------------------------------------------------------------------
// Benchmark Harness
// ----------------------------------------------------------------------------
struct alignas(mvcc::CACHE_LINE_SIZE) WorkerStats {
    uint64_t read_ops{0};
    uint64_t write_ops{0};
    uint64_t abort_count{0};
    std::vector<double> latencies_us;
};

void run_workload(
    const std::string& name,
    size_t num_threads,
    size_t duration_sec,
    double read_ratio,
    uint64_t key_space,
    double zipf_theta) 
{
    std::cout << "\n===============================================================\n";
    std::cout << "Starting Benchmark: " << name << "\n";
    std::cout << "Threads: " << num_threads 
              << " | Duration: " << duration_sec << "s"
              << " | Read Ratio: " << (read_ratio * 100.0) << "%"
              << " | Zipfian Theta: " << zipf_theta << "\n";
    std::cout << "===============================================================\n";

    mvcc::MVCCStorageEngine engine;

    // Pre-populate keys
    std::cout << "[Pre-populating " << key_space << " keys]..." << std::flush;
    {
        auto tx = engine.begin_transaction();
        for (uint64_t k = 0; k < key_space; ++k) {
            engine.put(tx, k, "init_val_" + std::to_string(k));
        }
        bool ok = engine.commit(tx);
        assert(ok && "Pre-population failed");
    }
    std::cout << " Done.\n";

    std::atomic<bool> stop_flag{false};
    std::atomic<bool> start_flag{false};
    std::vector<WorkerStats> stats(num_threads);
    std::vector<std::thread> workers;
    workers.reserve(num_threads);

    for (size_t tid = 0; tid < num_threads; ++tid) {
        workers.emplace_back([&, tid]() {
            std::mt19937_64 rng(1337 + tid);
            ZipfianGenerator zipf(key_space, zipf_theta);
            std::uniform_real_distribution<double> op_dist(0.0, 1.0);

            stats[tid].latencies_us.reserve(2000000);

            while (!start_flag.load(std::memory_order_relaxed)) {
                std::this_thread::yield();
            }

            while (!stop_flag.load(std::memory_order_relaxed)) {
                uint64_t key = zipf.next(rng) % key_space;
                bool is_read = (op_dist(rng) < read_ratio);

                auto t0 = std::chrono::high_resolution_clock::now();

                auto tx = engine.begin_transaction();
                if (is_read) {
                    std::string val;
                    engine.get(tx, key, val);
                    engine.commit(tx);
                    stats[tid].read_ops++;
                } else {
                    engine.put(tx, key, "updated_val_" + std::to_string(key));
                    if (engine.commit(tx)) {
                        stats[tid].write_ops++;
                    } else {
                        stats[tid].abort_count++;
                    }
                }

                auto t1 = std::chrono::high_resolution_clock::now();
                double us = std::chrono::duration<double, std::micro>(t1 - t0).count();
                stats[tid].latencies_us.push_back(us);
            }
        });
    }

    // Start benchmark timer
    start_flag.store(true, std::memory_order_release);
    auto start_time = std::chrono::high_resolution_clock::now();

    // Run maintenance GC cycle on main thread
    for (size_t sec = 0; sec < duration_sec; ++sec) {
        std::this_thread::sleep_for(std::chrono::seconds(1));
        engine.run_maintenance_cycle();
    }

    stop_flag.store(true, std::memory_order_release);
    for (auto& th : workers) {
        th.join();
    }
    auto end_time = std::chrono::high_resolution_clock::now();

    double total_sec = std::chrono::duration<double>(end_time - start_time).count();

    // Aggregate statistics
    uint64_t total_reads = 0;
    uint64_t total_writes = 0;
    uint64_t total_aborts = 0;
    std::vector<double> all_latencies;

    for (const auto& ws : stats) {
        total_reads += ws.read_ops;
        total_writes += ws.write_ops;
        total_aborts += ws.abort_count;
        all_latencies.insert(all_latencies.end(), ws.latencies_us.begin(), ws.latencies_us.end());
    }

    uint64_t total_ops = total_reads + total_writes;
    double mops = (static_cast<double>(total_ops) / total_sec) / 1e6;

    std::sort(all_latencies.begin(), all_latencies.end());
    auto get_percentile = [&](double pct) -> double {
        if (all_latencies.empty()) return 0.0;
        size_t idx = static_cast<size_t>(pct * static_cast<double>(all_latencies.size() - 1));
        return all_latencies[idx];
    };

    std::cout << std::fixed << std::setprecision(3);
    std::cout << "\n---------------- Results ----------------\n";
    std::cout << "Elapsed Time:      " << total_sec << " s\n";
    std::cout << "Throughput:        " << mops << " Million Ops/sec (Mops/s)\n";
    std::cout << "Total Read Ops:    " << total_reads << "\n";
    std::cout << "Total Write Ops:   " << total_writes << "\n";
    std::cout << "Total Aborts:      " << total_aborts << " (" 
              << (total_writes + total_aborts > 0 ? (double)total_aborts / (total_writes + total_aborts) * 100.0 : 0.0) 
              << "% of writes)\n";
    std::cout << "Latency p50:       " << get_percentile(0.50) << " us\n";
    std::cout << "Latency p90:       " << get_percentile(0.90) << " us\n";
    std::cout << "Latency p99:       " << get_percentile(0.99) << " us\n";
    std::cout << "Latency p99.9:     " << get_percentile(0.999) << " us\n";
    std::cout << "-----------------------------------------\n";
}

int main() {
    constexpr size_t KEY_SPACE = 50000;
    constexpr size_t DURATION_SEC = 3;
    const size_t NUM_THREADS = std::min<size_t>(std::thread::hardware_concurrency(), 32);

    std::cout << "Running MVCC Engine Tests on " << NUM_THREADS << " hardware threads.\n";

    // Workload 1: 90% Read / 10% Write, Skewed Zipfian (theta = 0.99)
    run_workload("90/10 Read-Heavy (Zipfian Skew theta=0.99)", 
                 NUM_THREADS, DURATION_SEC, 0.90, KEY_SPACE, 0.99);

    // Workload 2: 50% Read / 50% Write, High Contention (Zipfian Skew theta=0.99)
    run_workload("50/50 Balanced / High Contention (Zipfian Skew theta=0.99)", 
                 NUM_THREADS, DURATION_SEC, 0.50, KEY_SPACE, 0.99);

    return 0;
}
