## 2. Complete, Compilable Production-Grade C++20 Implementation

This implementation compiles under C++20 (`-std=c++20 -O3 -Wall -Wextra -luring -pthread`). It incorporates SSE4.2 hardware-accelerated CRC32C with a software fallback, Linux Futex primitives, 64-byte false-sharing elimination, and `io_uring` direct-I/O asynchronous log flushing.

```cpp
#include <iostream>
#include <vector>
#include <atomic>
#include <thread>
#include <chrono>
#include <cstring>
#include <memory>
#include <new>
#include <functional>
#include <array>
#include <cassert>
#include <cstdint>

// Linux & Direct-IO / io_uring / Futex headers
#include <fcntl.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <linux/futex.h>
#include <sys/mman.h>
#include <liburing.h>

#if defined(__x86_64__) || defined(_M_X64)
#include <nmmintrin.h>
#endif

// ============================================================================
// 1. CONSTANTS & SYSTEM CONFIGURATION
// ============================================================================
static constexpr size_t PAGE_SIZE           = 4096;
static constexpr size_t CACHELINE_SIZE      = 64;
static constexpr size_t MAX_THREADS         = 128;
static constexpr size_t WAL_RING_ENTRIES    = 65536;
static constexpr size_t WAL_RING_MASK       = WAL_RING_ENTRIES - 1;
static constexpr size_t IO_URING_QD         = 512;
static constexpr uint64_t EPOCH_LEASE_US    = 50000; // 50ms stall lease limit

using PageID = uint64_t;
using LSN    = uint64_t;
using TxnID  = uint64_t;

// Fast hardware-assisted CRC32C
inline uint32_t calculate_crc32c(const uint8_t* data, size_t length) {
    uint32_t crc = 0xFFFFFFFF;
#if defined(__x86_64__) || defined(_M_X64)
    size_t i = 0;
    for (; i + 8 <= length; i += 8) {
        crc = static_cast<uint32_t>(_mm_crc32_u64(crc, *reinterpret_cast<const uint64_t*>(data + i)));
    }
    for (; i < length; ++i) {
        crc = _mm_crc32_u8(crc, data[i]);
    }
#else
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc >> 1) ^ (0x82F63B78 & (-(crc & 1)));
        }
    }
#endif
    return ~crc;
}

// Fast userspace Linux futex helpers
inline int sys_futex(void* addr1, int op, int val1, const struct timespec* timeout, void* addr2, int val3) {
    return syscall(SYS_futex, addr1, op, val1, timeout, addr2, val3);
}

inline void futex_wait(std::atomic<uint32_t>* addr, uint32_t expected) {
    sys_futex(addr, FUTEX_WAIT_PRIVATE, static_cast<int>(expected), nullptr, nullptr, 0);
}

inline void futex_wake_all(std::atomic<uint32_t>* addr) {
    sys_futex(addr, FUTEX_WAKE_PRIVATE, INT32_MAX, nullptr, nullptr, 0);
}

// ============================================================================
// 2. MVCC PAGE STRUCTURES & DELTA STORAGE
// ============================================================================
struct alignas(CACHELINE_SIZE) VersionNode {
    LSN lsn;
    TxnID txn_id;
    VersionNode* next;
    alignas(PAGE_SIZE) uint8_t data[PAGE_SIZE];

    VersionNode(LSN lsn_, TxnID txn_, VersionNode* next_node = nullptr)
        : lsn(lsn_), txn_id(txn_), next(next_node) {
        std::memset(data, 0, PAGE_SIZE);
    }
};

struct alignas(CACHELINE_SIZE) MvccPageHeader {
    // Top-of-chain points to newest committed/in-flight version
    std::atomic<VersionNode*> head{nullptr};
    std::atomic<uint64_t> commit_lock{0}; // Bit 0: exclusive OCC lock if needed
};

// ============================================================================
// 3. STALL-RESILIENT EPOCH-BASED RECLAMATION (EBR)
// ============================================================================
class EpochManager {
public:
    struct alignas(CACHELINE_SIZE) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{UINT64_MAX};
        std::atomic<uint64_t> last_active_ts{0};
        std::atomic<bool>     registered{false};
    };

    struct RetiredNode {
        VersionNode* node;
        uint64_t epoch;
        RetiredNode* next;
    };

private:
    alignas(CACHELINE_SIZE) std::atomic<uint64_t> global_epoch{0};
    alignas(CACHELINE_SIZE) std::array<ThreadControlBlock, MAX_THREADS> tcbs;

    // Per-thread retired lists (epoch modulo 3)
    alignas(CACHELINE_SIZE) std::atomic<RetiredNode*> retired_heads[3]{nullptr, nullptr, nullptr};

public:
    EpochManager() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            tcbs[i].registered.store(false, std::memory_order_relaxed);
            tcbs[i].local_epoch.store(UINT64_MAX, std::memory_order_relaxed);
            tcbs[i].last_active_ts.store(0, std::memory_order_relaxed);
        }
    }

    ~EpochManager() {
        // Reclaim all remaining retired nodes across epochs
        for (int i = 0; i < 3; ++i) {
            RetiredNode* curr = retired_heads[i].exchange(nullptr, std::memory_order_relaxed);
            while (curr) {
                RetiredNode* next = curr->next;
                delete curr->node;
                delete curr;
                curr = next;
            }
        }
    }

    size_t register_thread() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (tcbs[i].registered.compare_exchange_strong(expected, true, 
                    std::memory_order_acq_rel, std::memory_order_relaxed)) {
                return i;
            }
        }
        throw std::runtime_error("Exceeded maximum thread capacity for EBR");
    }

    void unregister_thread(size_t tid) {
        tcbs[tid].local_epoch.store(UINT64_MAX, std::memory_order_release);
        tcbs[tid].registered.store(false, std::memory_order_release);
    }

    inline void enter(size_t tid) {
        uint64_t curr_epoch = global_epoch.load(std::memory_order_acquire);
        tcbs[tid].local_epoch.store(curr_epoch, std::memory_order_release);

        uint64_t now = std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now().time_since_epoch()).count();
        tcbs[tid].last_active_ts.store(now, std::memory_order_relaxed);
    }

    inline void exit(size_t tid) {
        // UINT64_MAX designates thread is outside critical section
        tcbs[tid].local_epoch.store(UINT64_MAX, std::memory_order_release);
    }

    void retire(VersionNode* node) {
        uint64_t e = global_epoch.load(std::memory_order_relaxed);
        size_t idx = e % 3;

        RetiredNode* r_node = new RetiredNode{node, e, nullptr};
        RetiredNode* old_head = retired_heads[idx].load(std::memory_order_relaxed);
        do {
            r_node->next = old_head;
        } while (!retired_heads[idx].compare_exchange_weak(old_head, r_node,
                    std::memory_order_release, std::memory_order_relaxed));
    }

    void try_advance_epoch() {
        uint64_t current_g_epoch = global_epoch.load(std::memory_order_acquire);
        uint64_t now = std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now().time_since_epoch()).count();

        // Check if all active non-stalled threads have observed current_g_epoch
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (!tcbs[i].registered.load(std::memory_order_relaxed)) continue;

            uint64_t th_epoch = tcbs[i].local_epoch.load(std::memory_order_acquire);
            if (th_epoch != UINT64_MAX && th_epoch < current_g_epoch) {
                // Lease fallback: check if thread has stalled longer than EPOCH_LEASE_US
                uint64_t last_seen = tcbs[i].last_active_ts.load(std::memory_order_relaxed);
                if (now - last_seen < EPOCH_LEASE_US) {
                    return; // Thread still legitimately executing within lease window
                }
                // Thread is deemed stalled/crashed: skip it to prevent unconstrained memory growth
            }
        }

        // Advance global epoch
        if (global_epoch.compare_exchange_strong(current_g_epoch, current_g_epoch + 1,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            // Safe to reclaim nodes from 2 epochs prior
            size_t reclaim_idx = (current_g_epoch + 2) % 3;
            reclaim_epoch_nodes(reclaim_idx);
        }
    }

private:
    void reclaim_epoch_nodes(size_t idx) {
        RetiredNode* head = retired_heads[idx].exchange(nullptr, std::memory_order_acq_rel);
        while (head) {
            RetiredNode* next = head->next;
            delete head->node;
            delete head;
            head = next;
        }
    }
};

// ============================================================================
// 4. LOCK-FREE WAL LOG ENTRY & RING BUFFER
// ============================================================================
#pragma pack(push, 1)
struct WalRecordHeader {
    LSN      lsn;
    TxnID    txn_id;
    PageID   page_id;
    uint32_t payload_size;
    uint32_t crc32c;
    uint64_t padding; // Align header to 32 bytes
};
#pragma pack(pop)

static_assert(sizeof(WalRecordHeader) == 32, "WalRecordHeader must be exactly 32 bytes");

struct alignas(64) WalSlot {
    std::atomic<uint64_t> sequence;
    WalRecordHeader       header;
    alignas(64) uint8_t   payload[PAGE_SIZE];
};

class LockFreeWalQueue {
private:
    WalSlot* buffer_;
    alignas(CACHELINE_SIZE) std::atomic<uint64_t> enqueue_pos_{0};
    alignas(CACHELINE_SIZE) std::atomic<uint64_t> dequeue_pos_{0};

public:
    LockFreeWalQueue() {
        // Allocate 4KB-aligned buffer memory for direct O_DIRECT suitability
        void* ptr = nullptr;
        if (posix_memalign(&ptr, PAGE_SIZE, sizeof(WalSlot) * WAL_RING_ENTRIES) != 0) {
            throw std::bad_alloc();
        }
        buffer_ = static_cast<WalSlot*>(ptr);
        for (size_t i = 0; i < WAL_RING_ENTRIES; ++i) {
            buffer_[i].sequence.store(i, std::memory_order_relaxed);
        }
    }

    ~LockFreeWalQueue() {
        free(buffer_);
    }

    bool enqueue(LSN lsn, TxnID txn_id, PageID page_id, const uint8_t* page_data) {
        uint64_t pos = enqueue_pos_.load(std::memory_order_relaxed);
        for (;;) {
            WalSlot* slot = &buffer_[pos & WAL_RING_MASK];
            uint64_t seq = slot->sequence.load(std::memory_order_acquire);
            int64_t dif = static_cast<int64_t>(seq) - static_cast<int64_t>(pos);

            if (dif == 0) {
                if (enqueue_pos_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                    // Prepare Log Record
                    slot->header.lsn = lsn;
                    slot->header.txn_id = txn_id;
                    slot->header.page_id = page_id;
                    slot->header.payload_size = PAGE_SIZE;
                    std::memcpy(slot->payload, page_data, PAGE_SIZE);

                    slot->header.crc32c = calculate_crc32c(slot->payload, PAGE_SIZE);

                    // Publish slot ready for flusher
                    slot->sequence.store(pos + 1, std::memory_order_release);
                    return true;
                }
            } else if (dif < 0) {
                // Buffer full
                return false;
            } else {
                pos = enqueue_pos_.load(std::memory_order_relaxed);
            }
        }
    }

    bool peek(uint64_t& pos, WalSlot*& slot) {
        pos = dequeue_pos_.load(std::memory_order_relaxed);
        slot = &buffer_[pos & WAL_RING_MASK];
        uint64_t seq = slot->sequence.load(std::memory_order_acquire);
        int64_t dif = static_cast<int64_t>(seq) - static_cast<int64_t>(pos + 1);
        if (dif == 0) {
            return true;
        }
        return false;
    }

    void advance_dequeue(uint64_t pos) {
        WalSlot* slot = &buffer_[pos & WAL_RING_MASK];
        slot->sequence.store(pos + WAL_RING_MASK + 1, std::memory_order_release);
        dequeue_pos_.store(pos + 1, std::memory_order_relaxed);
    }
};

// ============================================================================
// 5. ASYNCHRONOUS io_uring WAL ENGINE WITH OUT-OF-ORDER LSN WATERMARKING
// ============================================================================
class IoUringWalEngine {
private:
    int wal_fd_{-1};
    struct io_uring ring_;
    std::atomic<bool> running_{false};
    std::thread flusher_thread_;

    // Monotonically increasing LSN counters
    alignas(CACHELINE_SIZE) std::atomic<LSN> global_lsn_counter_{1};
    alignas(CACHELINE_SIZE) std::atomic<LSN> durable_lsn_watermark_{0};
    alignas(CACHELINE_SIZE) std::atomic<uint32_t> futex_word_{0};

    // Aligned write buffer for direct I/O submissions
    alignas(PAGE_SIZE) uint8_t direct_io_buffer_[PAGE_SIZE * IO_URING_QD];
    uint64_t file_offset_{0};

    LockFreeWalQueue& queue_;

    struct IOContext {
        LSN max_batch_lsn;
        uint64_t buffer_idx;
        bool is_sync;
    };

public:
    IoUringWalEngine(const char* wal_file_path, LockFreeWalQueue& queue)
        : queue_(queue) {
        wal_fd_ = open(wal_file_path, O_DIRECT | O_RDWR | O_CREAT | O_TRUNC, 0644);
        if (wal_fd_ < 0) {
            throw std::system_error(errno, std::generic_category(), "Failed to open WAL file with O_DIRECT");
        }

        struct io_uring_params params;
        std::memset(&params, 0, sizeof(params));
        // Use SQPOLL kernel thread if available to reduce syscall overhead
        params.flags = IORING_SETUP_SQPOLL;
        params.sq_thread_idle = 2000;

        int ret = io_uring_queue_init_params(IO_URING_QD, &ring_, &params);
        if (ret < 0) {
            // Fallback without SQPOLL if permissions/support unavailable
            ret = io_uring_queue_init(IO_URING_QD, &ring_, 0);
            if (ret < 0) {
                close(wal_fd_);
                throw std::system_error(-ret, std::generic_category(), "io_uring_queue_init failed");
            }
        }

        running_.store(true, std::memory_order_relaxed);
        flusher_thread_ = std::thread(&IoUringWalEngine::flusher_loop, this);
    }

    ~IoUringWalEngine() {
        running_.store(false, std::memory_order_release);
        if (flusher_thread_.joinable()) {
            flusher_thread_.join();
        }
        io_uring_queue_exit(&ring_);
        if (wal_fd_ >= 0) {
            close(wal_fd_);
        }
    }

    LSN allocate_lsn() {
        return global_lsn_counter_.fetch_add(1, std::memory_order_relaxed);
    }

    void wait_durable(LSN lsn) {
        while (durable_lsn_watermark_.load(std::memory_order_acquire) < lsn) {
            uint32_t old_val = futex_word_.load(std::memory_order_relaxed);
            if (durable_lsn_watermark_.load(std::memory_order_acquire) >= lsn) break;
            futex_wait(&futex_word_, old_val);
        }
    }

private:
    void flusher_loop() {
        std::vector<IOContext> in_flight_contexts(IO_URING_QD);
        size_t inflight_count = 0;

        while (running_.load(std::memory_order_relaxed) || inflight_count > 0) {
            uint64_t deq_pos;
            WalSlot* slot;
            LSN highest_lsn_in_batch = 0;
            size_t batch_size = 0;

            // 1. Drain entries from MPSC queue into aligned buffer
            while (batch_size < IO_URING_QD && queue_.peek(deq_pos, slot)) {
                uint8_t* dest = &direct_io_buffer_[batch_size * PAGE_SIZE];

                // Pack header and payload contiguously into 4096-byte chunk
                std::memcpy(dest, &slot->header, sizeof(WalRecordHeader));
                std::memcpy(dest + sizeof(WalRecordHeader), slot->payload, PAGE_SIZE - sizeof(WalRecordHeader));

                highest_lsn_in_batch = std::max(highest_lsn_in_batch, slot->header.lsn);
                queue_.advance_dequeue(deq_pos);
                batch_size++;
            }

            // 2. Submit Direct-I/O write if batch populated
            if (batch_size > 0) {
                struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
                if (!sqe) {
                    io_uring_submit(&ring_);
                    sqe = io_uring_get_sqe(&ring_);
                }

                IOContext& ctx = in_flight_contexts[inflight_count % IO_URING_QD];
                ctx.max_batch_lsn = highest_lsn_in_batch;
                ctx.is_sync = false;

                io_uring_prep_write(sqe, wal_fd_, direct_io_buffer_, batch_size * PAGE_SIZE, file_offset_);
                io_uring_sqe_set_data(sqe, &ctx);
                file_offset_ += (batch_size * PAGE_SIZE);
                inflight_count++;

                // Issue linked fdatasync command
                struct io_uring_sqe* sync_sqe = io_uring_get_sqe(&ring_);
                if (sync_sqe) {
                    IOContext& sync_ctx = in_flight_contexts[inflight_count % IO_URING_QD];
                    sync_ctx.max_batch_lsn = highest_lsn_in_batch;
                    sync_ctx.is_sync = true;

                    io_uring_prep_fsync(sync_sqe, wal_fd_, IORING_FSYNC_DATASYNC);
                    io_uring_sqe_set_data(sync_sqe, &sync_ctx);
                    inflight_count++;
                }

                io_uring_submit(&ring_);
            }

            // 3. Harvest CQEs and advance LSN watermark monotonically
            struct io_uring_cqe* cqe = nullptr;
            unsigned head;
            unsigned count = 0;
            LSN max_completed_sync_lsn = 0;

            io_uring_for_each_cqe(&ring_, head, cqe) {
                count++;
                if (cqe->res >= 0) {
                    IOContext* completed_ctx = static_cast<IOContext*>(io_uring_cqe_get_data(cqe));
                    if (completed_ctx && completed_ctx->is_sync) {
                        max_completed_sync_lsn = std::max(max_completed_sync_lsn, completed_ctx->max_batch_lsn);
                    }
                }
            }

            if (count > 0) {
                io_uring_cq_advance(&ring_, count);
                inflight_count -= count;

                if (max_completed_sync_lsn > 0) {
                    // Update durable watermark with release semantics to make WAL writes visible
                    LSN prev = durable_lsn_watermark_.load(std::memory_order_relaxed);
                    while (max_completed_sync_lsn > prev && 
                           !durable_lsn_watermark_.compare_exchange_weak(prev, max_completed_sync_lsn,
                                std::memory_order_release, std::memory_order_relaxed));

                    // Wake threads waiting on durable transaction completion
                    futex_word_.fetch_add(1, std::memory_order_release);
                    futex_wake_all(&futex_word_);
                }
            }

            if (batch_size == 0 && inflight_count == 0) {
                std::this_thread::yield();
            }
        }
    }
};

// ============================================================================
// 6. MVCC PAGE CACHE & TRANSACTION MANAGER
// ============================================================================
class MvccPageCache {
private:
    static constexpr size_t NUM_PAGES = 1024;
    std::array<MvccPageHeader, NUM_PAGES> page_table_;
    EpochManager epoch_mgr_;
    LockFreeWalQueue wal_queue_;
    IoUringWalEngine wal_engine_;

public:
    MvccPageCache(const char* wal_path)
        : wal_engine_(wal_path, wal_queue_) {
        // Initialize base page versions
        for (size_t i = 0; i < NUM_PAGES; ++i) {
            VersionNode* base_node = new VersionNode(0, 0);
            page_table_[i].head.store(base_node, std::memory_order_relaxed);
        }
    }

    ~MvccPageCache() {
        for (size_t i = 0; i < NUM_PAGES; ++i) {
            VersionNode* curr = page_table_[i].head.load(std::memory_order_relaxed);
            while (curr) {
                VersionNode* nxt = curr->next;
                delete curr;
                curr = nxt;
            }
        }
    }

    EpochManager& get_epoch_manager() { return epoch_mgr_; }

    // Lock-free read operation: Traverses version chain without exclusive locks
    bool read_page(size_t tid, PageID pid, LSN read_timestamp, uint8_t* out_buffer, VersionNode*& observed_head) {
        assert(pid < NUM_PAGES);
        epoch_mgr_.enter(tid);

        // Acquire memory order guarantees we observe updated payload written before publication
        VersionNode* curr = page_table_[pid].head.load(std::memory_order_acquire);
        observed_head = curr;

        while (curr != nullptr) {
            // Visibility Rule: Visible only if version LSN <= transaction Read Timestamp
            if (curr->lsn <= read_timestamp) {
                std::memcpy(out_buffer, curr->data, PAGE_SIZE);
                epoch_mgr_.exit(tid);
                return true;
            }
            curr = curr->next;
        }

        epoch_mgr_.exit(tid);
        return false;
    }

    // OCC Commit Operation with First-Committer-Wins validation
    bool commit_update(size_t tid, TxnID txn_id, PageID pid, const uint8_t* new_data, VersionNode* expected_head) {
        assert(pid < NUM_PAGES);
        epoch_mgr_.enter(tid);

        // 1. OCC Validation (CAS against current chain head)
        VersionNode* current_head = page_table_[pid].head.load(std::memory_order_acquire);
        if (current_head != expected_head) {
            // First-Committer-Wins: Newer version already committed -> Abort
            epoch_mgr_.exit(tid);
            return false;
        }

        // 2. Allocate Monotonic LSN
        LSN allocated_lsn = wal_engine_.allocate_lsn();

        // 3. Prepare speculative version node
        VersionNode* new_version = new VersionNode(allocated_lsn, txn_id, expected_head);
        std::memcpy(new_version->data, new_data, PAGE_SIZE);

        // 4. Enqueue into WAL Engine
        while (!wal_queue_.enqueue(allocated_lsn, txn_id, pid, new_data)) {
            std::this_thread::yield();
        }

        // 5. Crash-Consistency Gate: Block until LSN is durable on NVMe
        wal_engine_.wait_durable(allocated_lsn);

        // 6. Publication via CAS (Release ordering guarantees durable writes are observed)
        if (!page_table_[pid].head.compare_exchange_strong(expected_head, new_version,
                std::memory_order_release, std::memory_order_acquire)) {
            // Conflict occurred during WAL persistence window: abort and retire node
            epoch_mgr_.retire(new_version);
            epoch_mgr_.exit(tid);
            return false;
        }

        // 7. Chain Maintenance: Retire stale version for deferred reclamation
        if (expected_head != nullptr && expected_head->next != nullptr) {
            epoch_mgr_.retire(expected_head->next);
        }

        epoch_mgr_.try_advance_epoch();
        epoch_mgr_.exit(tid);
        return true;
    }
};

// ============================================================================
// 7. VERIFICATION HARNESS & STRESS TEST
