// ============================================================================
// Low-Level Architecture & Futex Helpers
// ============================================================================

static inline int sys_futex(void* uaddr, int futex_op, int val,
                            const struct timespec* timeout, int* uaddr2, int val3) {
    return syscall(SYS_futex, uaddr, futex_op, val, timeout, uaddr2, val3);
}

static inline void futex_wait(std::atomic<uint32_t>* addr, uint32_t expected) {
    while (addr->load(std::memory_order_acquire) == expected) {
        sys_futex(reinterpret_cast<void*>(addr), FUTEX_WAIT_PRIVATE, static_cast<int>(expected), nullptr, nullptr, 0);
    }
}

static inline void futex_wake_all(std::atomic<uint32_t>* addr) {
    sys_futex(reinterpret_cast<void*>(addr), FUTEX_WAKE_PRIVATE, INT32_MAX, nullptr, nullptr, 0);
}

// CRC32C software implementation (Castagnoli polynomial 0x82F63B78)
static inline uint32_t crc32c(uint32_t crc, const uint8_t* buf, size_t len) {
    crc = ~crc;
    while (len--) {
        crc ^= *buf++;
        for (int k = 0; k < 8; k++) {
            crc = (crc >> 1) ^ (0x82F63B78u & (0 - (crc & 1)));
        }
    }
    return ~crc;
}

