constexpr size_t PAGE_SIZE = 4096;
constexpr size_t BLOCK_ALIGNMENT = 4096;
constexpr size_t MAX_THREADS = 64;
constexpr uint64_t INVALID_LSN = 0;
constexpr uint64_t INVALID_TS = 0;

struct PageVersion {
    uint64_t commit_ts{INVALID_TS};
    uint64_t lsn{INVALID_LSN};
    uint64_t page_id{0};

    // ABA Prevention tag & chain linkage
    alignas(std::hardware_destructive_interference_size) 
    std::atomic<PageVersion*> next_version{nullptr};

    // Lease count for fallback reclamation when threads stall
    alignas(std::hardware_destructive_interference_size)
    std::atomic<uint32_t> lease_count{0};

    uint32_t payload_size{0};
    alignas(BLOCK_ALIGNMENT) uint8_t data[PAGE_SIZE];

    PageVersion() = default;
};

// ============================================================================
// 3. Epoch-Based Reclamation (EBR) with Stall Resilience
// ============================================================================

class EpochManager {
public:
    static constexpr size_t NUM_EPOCHS = 3;
    static constexpr uint64_t STALL_THRESHOLD_MS = 200;

    struct alignas(std::hardware_destructive_interference_size) ThreadDescriptor {
        std::atomic<uint64_t> active_epoch{UINT64_MAX};
        std::atomic<bool> in_critical_section{false};
        std::atomic<uint64_t> entry_timestamp_ms{0};
        std::atomic<bool> registered{false};
    };

    struct alignas(std::hardware_destructive_interference_size) RetiredNode {
        PageVersion* node;
        RetiredNode* next;
    };

private:
    alignas(std::hardware_destructive_interference_size) 
    std::atomic<uint64_t> global_epoch_{0};

    alignas(std::hardware_destructive_interference_size) 
    std::array<ThreadDescriptor, MAX_THREADS> threads_{};

    alignas(std::hardware_destructive_interference_size)
    std::array<std::atomic<RetiredNode*>, NUM_EPOCHS> retirement_lists_{};

    static inline uint64_t get_time_ms() {
        return static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now().time_since_epoch()).count());
    }

public:
    EpochManager() {
        for (auto& head : retirement_lists_) {
            head.store(nullptr, std::memory_order_relaxed);
        }
    }

    ~EpochManager() {
        for (size_t i = 0; i < NUM_EPOCHS; ++i) {
            reclaim_epoch(i);
        }
    }

    size_t register_thread() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (threads_[i].registered.compare_exchange_strong(expected, true, 
                                                              std::memory_order_acq_rel, 
                                                              std::memory_order_relaxed)) {
                return i;
            }
        }
        throw std::runtime_error("Exceeded maximum supported worker threads.");
    }

    void unregister_thread(size_t tid) {
        threads_[tid].in_critical_section.store(false, std::memory_order_release);
        threads_[tid].active_epoch.store(UINT64_MAX, std::memory_order_release);
        threads_[tid].registered.store(false, std::memory_order_release);
    }

    inline void enter_critical_section(size_t tid) {
        // Relaxed fetch of global epoch followed by an acquire barrier on active flag
        uint64_t e = global_epoch_.load(std::memory_order_relaxed);
        threads_[tid].active_epoch.store(e, std::memory_order_relaxed);
        threads_[tid].entry_timestamp_ms.store(get_time_ms(), std::memory_order_relaxed);

        // Full Store-Load barrier required to prevent read hoisting prior to registration
        threads_[tid].in_critical_section.store(true, std::memory_order_seq_cst);
    }

    inline void exit_critical_section(size_t tid) {
        threads_[tid].in_critical_section.store(false, std::memory_order_release);
        threads_[tid].active_epoch.store(UINT64_MAX, std::memory_order_relaxed);
    }

    void retire_version(PageVersion* v) {
        if (!v) return;

        uint64_t current_e = global_epoch_.load(std::memory_order_relaxed);
        size_t idx = current_e % NUM_EPOCHS;

        auto* node = new RetiredNode{v, nullptr};
        RetiredNode* old_head = retirement_lists_[idx].load(std::memory_order_relaxed);

        // Push to lock-free singly-linked retirement stack
        do {
            node->next = old_head;
        } while (!retirement_lists_[idx].compare_exchange_weak(
            old_head, node, 
            std::memory_order_release, 
            std::memory_order_relaxed));
    }

    void try_advance_epoch() {
        uint64_t current_e = global_epoch_.load(std::memory_order_relaxed);
        uint64_t now = get_time_ms();

        // Check if all threads have observed the current epoch or are stalled
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (!threads_[i].registered.load(std::memory_order_relaxed)) continue;

            if (threads_[i].in_critical_section.load(std::memory_order_acquire)) {
                uint64_t thread_epoch = threads_[i].active_epoch.load(std::memory_order_relaxed);
                if (thread_epoch < current_e) {
                    // Stall Resilience: Check if thread exceeded bounded lease duration
                    uint64_t duration = now - threads_[i].entry_timestamp_ms.load(std::memory_order_relaxed);
                    if (duration < STALL_THRESHOLD_MS) {
                        return; // Cannot safely advance; valid reader exists within grace window
                    }
                    // Thread is stalled/preempted: Fall back to checking individual version leases
                }
            }
        }

        // Try to advance global epoch using CAS
        if (global_epoch_.compare_exchange_strong(current_e, current_e + 1,
                                                  std::memory_order_acq_rel,
                                                  std::memory_order_relaxed)) {
            // Safe to reclaim (current_e - 1) which corresponds to (current_e + 2) % 3
            size_t reclaim_idx = (current_e + NUM_EPOCHS - 1) % NUM_EPOCHS;
            reclaim_epoch(reclaim_idx);
        }
    }

private:
    void reclaim_epoch(size_t idx) {
        RetiredNode* head = retirement_lists_[idx].exchange(nullptr, std::memory_order_acq_rel);
        while (head) {
            RetiredNode* next = head->next;
            // Free only if fallback lease refcount is zero
            if (head->node->lease_count.load(std::memory_order_acquire) == 0) {
                ::free(head->node);
            }
            delete head;
            head = next;
        }
    }
};

// ============================================================================
// 2. Lock-Free MPSC WAL Ring Buffer with io_uring Integration
// ============================================================================

struct alignas(BLOCK_ALIGNMENT) WalRecord {
    uint32_t magic{0x57414C52}; // 'WALR'
    uint32_t checksum{0};
    uint64_t lsn{0};
    uint64_t page_id{0};
    uint32_t payload_len{0};
    uint8_t payload[PAGE_SIZE - 24]; // Pad to exactly 4096 bytes
};
static_assert(sizeof(WalRecord) == BLOCK_ALIGNMENT, "WalRecord must be exactly 4096-byte aligned.");

class LockFreeWalQueue {
public:
    static constexpr size_t CAPACITY = 1024; // 4MB Buffer Ring

    struct Slot {
        alignas(std::hardware_destructive_interference_size) std::atomic<uint64_t> sequence;
        WalRecord record;
    };

private:
    alignas(BLOCK_ALIGNMENT) Slot ring_[CAPACITY];

    alignas(std::hardware_destructive_interference_size) 
    std::atomic<uint64_t> tail_{0}; // Producer ticket dispenser

    alignas(std::hardware_destructive_interference_size) 
    uint64_t head_{0}; // Single-consumer drain position

public:
    LockFreeWalQueue() {
        for (size_t i = 0; i < CAPACITY; ++i) {
            ring_[i].sequence.store(i, std::memory_order_relaxed);
        }
    }

    bool enqueue(uint64_t lsn, uint64_t page_id, const uint8_t* data, size_t len) {
        uint64_t current_tail = tail_.load(std::memory_order_relaxed);
        Slot* slot;

        for (;;) {
            slot = &ring_[current_tail & (CAPACITY - 1)];
            uint64_t seq = slot->sequence.load(std::memory_order_acquire);
            int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(current_tail);

            if (diff == 0) {
                // Slot is free for allocation; try to claim it
                if (tail_.compare_exchange_weak(current_tail, current_tail + 1,
                                                std::memory_order_acq_rel,
                                                std::memory_order_relaxed)) {
                    break;
                }
            } else if (diff < 0) {
                // Queue full
                return false;
            } else {
                current_tail = tail_.load(std::memory_order_relaxed);
            }
        }

        // Populate slot
        slot->record.magic = 0x57414C52;
        slot->record.lsn = lsn;
        slot->record.page_id = page_id;
        slot->record.payload_len = static_cast<uint32_t>(len);
        std::memcpy(slot->record.payload, data, len);

        // Checksum calculation (protects against torn writes / tail corruption)
        slot->record.checksum = 0;
        slot->record.checksum = crc32c(0, reinterpret_cast<const uint8_t*>(&slot->record), sizeof(WalRecord));

        // Publish record readiness to single flusher thread
        slot->sequence.store(current_tail + 1, std::memory_order_release);
        return true;
    }

    size_t drain_batch(std::span<WalRecord*> batch_dest, size_t max_items) {
        size_t count = 0;
        while (count < max_items) {
            Slot* slot = &ring_[head_ & (CAPACITY - 1)];
            uint64_t seq = slot->sequence.load(std::memory_order_acquire);
            int64_t diff = static_cast<int64_t>(seq) - static_cast<int64_t>(head_ + 1);

            if (diff == 0) {
                batch_dest[count++] = &slot->record;
                head_++;
            } else {
                break; // No more ready entries
            }
        }
        return count;
    }

    void release_batch(size_t count) {
        uint64_t base = head_ - count;
        for (size_t i = 0; i < count; ++i) {
            Slot* slot = &ring_[(base + i) & (CAPACITY - 1)];
            // Reset sequence to allow wrap-around reuse
            slot->sequence.store((base + i) + CAPACITY, std::memory_order_release);
        }
    }
};

class IoUringWalEngine {
public:
    static constexpr size_t QUEUE_DEPTH = 256;
    static constexpr size_t MAX_BATCH = 64;

private:
    int fd_{-1};
    struct io_uring ring_{};
    LockFreeWalQueue queue_;

    alignas(std::hardware_destructive_interference_size)
    std::atomic<uint64_t> next_lsn_{1};

    alignas(std::hardware_destructive_interference_size)
    std::atomic<uint64_t> durable_lsn_{0};

    alignas(std::hardware_destructive_interference_size)
    std::atomic<uint32_t> futex_lsn_signal_{0};

    std::atomic<bool> running_{false};
    std::thread flusher_thread_;
    uint64_t file_offset_{0};

    // Watermark map to track out-of-order completions in io_uring
    struct alignas(std::hardware_destructive_interference_size) LsnWatermarkTracker {
        static constexpr size_t WINDOW_SIZE = 1024;
        std::atomic<bool> completed[WINDOW_SIZE];
        uint64_t base_lsn{1};

        LsnWatermarkTracker() {
            for (size_t i = 0; i < WINDOW_SIZE; ++i) completed[i].store(false, std::memory_order_relaxed);
        }

        void mark_completed(uint64_t lsn) {
            assert(lsn >= base_lsn);
            size_t idx = (lsn - base_lsn) % WINDOW_SIZE;
            completed[idx].store(true, std::memory_order_release);
        }

        uint64_t advance_contiguous() {
            uint64_t advanced = base_lsn;
            while (true) {
                size_t idx = (advanced - base_lsn) % WINDOW_SIZE;
                if (completed[idx].load(std::memory_order_acquire)) {
                    completed[idx].store(false, std::memory_order_relaxed);
                    advanced++;
                } else {
                    break;
                }
            }
            uint64_t newly_durable = advanced - 1;
            base_lsn = advanced;
            return newly_durable;
        }
    } watermark_tracker_;

public:
    explicit IoUringWalEngine(const char* log_path) {
        // Direct I/O flags with kernel SQPOLL for minimal userspace-kernel transition overhead
        fd_ = ::open(log_path, O_CREAT | O_RDWR | O_DIRECT | O_TRUNC, 0644);
        if (fd_ < 0) throw std::system_error(errno, std::generic_category(), "open O_DIRECT failed");

        struct io_uring_params params{};
        params.flags = IORING_SETUP_SQPOLL;
        params.sq_thread_idle = 2000; // 2s polling idle window before kernel thread sleeps

        int ret = io_uring_queue_init_params(QUEUE_DEPTH, &ring_, &params);
        if (ret < 0) {
            // Fallback without SQPOLL if permissions/limits disallow
            ret = io_uring_queue_init(QUEUE_DEPTH, &ring_, 0);
            if (ret < 0) throw std::system_error(-ret, std::generic_category(), "io_uring_queue_init failed");
        }

        running_.store(true, std::memory_order_release);
        flusher_thread_ = std::thread(&IoUringWalEngine::flusher_loop, this);
    }

    ~IoUringWalEngine() {
        running_.store(false, std::memory_order_release);
        if (flusher_thread_.joinable()) flusher_thread_.join();
        io_uring_queue_exit(&ring_);
        if (fd_ >= 0) ::close(fd_);
    }

    uint64_t append_log(uint64_t page_id, const uint8_t* data, size_t len) {
        uint64_t lsn = next_lsn_.fetch_add(1, std::memory_order_acq_rel);

        while (!queue_.enqueue(lsn, page_id, data, len)) {
            std::this_thread::yield();
        }
        return lsn;
    }

    void wait_for_durable(uint64_t target_lsn) {
        while (durable_lsn_.load(std::memory_order_acquire) < target_lsn) {
            futex_wait(&futex_lsn_signal_, futex_lsn_signal_.load(std::memory_order_relaxed));
        }
    }

    uint64_t get_durable_lsn() const {
        return durable_lsn_.load(std::memory_order_acquire);
    }

private:
    void flusher_loop() {
        std::array<WalRecord*, MAX_BATCH> batch{};

        while (running_.load(std::memory_order_acquire)) {
            size_t count = queue_.drain_batch(batch, MAX_BATCH);

            if (count > 0) {
                for (size_t i = 0; i < count; ++i) {
                    struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
                    while (!sqe) {
                        io_uring_submit(&ring_);
                        sqe = io_uring_get_sqe(&ring_);
                    }

                    // Direct-I/O write submission
                    io_uring_prep_write(sqe, fd_, batch[i], BLOCK_ALIGNMENT, file_offset_);
                    io_uring_sqe_set_data(sqe, batch[i]);
                    file_offset_ += BLOCK_ALIGNMENT;
                }

                io_uring_submit(&ring_);
                queue_.release_batch(count);
            }

            // Harvest completions
            struct io_uring_cqe* cqe = nullptr;
            unsigned head = 0;
            unsigned cqe_count = 0;
            bool newly_completed = false;

            io_uring_for_each_cqe(&ring_, head, cqe) {
                cqe_count++;
                if (cqe->res < 0) {
                    std::cerr << "io_uring async write failure: " << cqe->res << std::endl;
                } else {
                    auto* rec = reinterpret_cast<WalRecord*>(io_uring_cqe_get_data(cqe));
                    watermark_tracker_.mark_completed(rec->lsn);
                    newly_completed = true;
                }
            }

            if (cqe_count > 0) {
                io_uring_cq_advance(&ring_, cqe_count);
            }

            if (newly_completed) {
                uint64_t max_durable = watermark_tracker_.advance_contiguous();
                if (max_durable > durable_lsn_.load(std::memory_order_relaxed)) {
                    durable_lsn_.store(max_durable, std::memory_order_release);
                    futex_lsn_signal_.fetch_add(1, std::memory_order_release);
                    futex_wake_all(&futex_lsn_signal_);
                }
            }

            if (count == 0 && cqe_count == 0) {
                std::this_thread::yield();
            }
        }
    }
};

// ============================================================================
// 1. MVCC Page Cache Management
// ============================================================================

class alignas(std::hardware_destructive_interference_size) MvccPageHeader {
public:
    const uint64_t page_id;

    // Head points to newest committed version
    alignas(std::hardware_destructive_interference_size) 
    std::atomic<PageVersion*> head{nullptr};

    explicit MvccPageHeader(uint64_t id) : page_id(id) {}

    ~MvccPageHeader() {
        PageVersion* curr = head.load(std::memory_order_relaxed);
        while (curr) {
            PageVersion* next = curr->next_version.load(std::memory_order_relaxed);
            ::free(curr);
            curr = next;
        }
    }
};

class MvccEngine {
private:
    EpochManager epoch_mgr_;
    IoUringWalEngine wal_engine_;

    alignas(std::hardware_destructive_interference_size)
    std::atomic<uint64_t> global_ts_{1};

    std::vector<std::unique_ptr<MvccPageHeader>> pages_;

public:
    MvccEngine(size_t num_pages, const char* wal_path) 
        : wal_engine_(wal_path) {
        pages_.reserve(num_pages);
        for (size_t i = 0; i < num_pages; ++i) {
            pages_.push_back(std::make_unique<MvccPageHeader>(i));

            // Seed Genesis Version
            void* raw_mem = nullptr;
            posix_memalign(&raw_mem, BLOCK_ALIGNMENT, sizeof(PageVersion));
            auto* genesis = new (raw_mem) PageVersion();
            genesis->commit_ts = 0;
            genesis->lsn = 0;
            genesis->page_id = i;
            genesis->payload_size = PAGE_SIZE;
            std::memset(genesis->data, 0, PAGE_SIZE);
            pages_[i]->head.store(genesis, std::memory_order_release);
        }
    }

    size_t register_worker() {
        return epoch_mgr_.register_thread();
    }

    void unregister_worker(size_t tid) {
        epoch_mgr_.unregister_thread(tid);
    }

    // Lock-Free Snapshot Read
    bool read_page(size_t tid, uint64_t page_id, uint64_t read_ts, uint8_t* out_buffer) {
        epoch_mgr_.enter_critical_section(tid);

        MvccPageHeader* page = pages_[page_id].get();
        PageVersion* curr = page->head.load(std::memory_order_acquire);
        uint64_t current_durable_lsn = wal_engine_.get_durable_lsn();

        bool success = false;
        while (curr) {
            // Invariant: Version must be committed prior to read_ts AND durably persisted
            if (curr->commit_ts <= read_ts && curr->lsn <= current_durable_lsn) {
                // Hazard refcount lease acquisition for stall-resilience fallback
                curr->lease_count.fetch_add(1, std::memory_order_acquire);

                std::memcpy(out_buffer, curr->data, curr->payload_size);

                curr->lease_count.fetch_sub(1, std::memory_order_release);
                success = true;
                break;
            }
            curr = curr->next_version.load(std::memory_order_acquire);
        }

        epoch_mgr_.exit_critical_section(tid);
        return success;
    }

    // Optimistic Concurrency Control (OCC) First-Committer-Wins Update
    bool update_page(size_t tid, uint64_t page_id, uint64_t read_ts, const uint8_t* new_data, size_t len) {
        MvccPageHeader* page = pages_[page_id].get();

        epoch_mgr_.enter_critical_section(tid);

        PageVersion* current_head = page->head.load(std::memory_order_acquire);

        // OCC Conflict Check: If current version is newer than read snapshot -> Abort
        if (current_head->commit_ts > read_ts) {
            epoch_mgr_.exit_critical_section(tid);
            return false; // First-committer-wins conflict
        }

        // Prepare new version
        void* raw_mem = nullptr;
        posix_memalign(&raw_mem, BLOCK_ALIGNMENT, sizeof(PageVersion));
        auto* new_version = new (raw_mem) PageVersion();
        new_version->page_id = page_id;
        new_version->payload_size = static_cast<uint32_t>(len);
        std::memcpy(new_version->data, new_data, len);

        // Reserve next global logical timestamp
        uint64_t commit_ts = global_ts_.fetch_add(1, std::memory_order_acq_rel);
        new_version->commit_ts = commit_ts;

        // Stage into WAL Engine and obtain LSN
        uint64_t lsn = wal_engine_.append_log(page_id, new_data, len);
        new_version->lsn = lsn;

        // Wait for Durability Barrier before publishing version to index
        wal_engine_.wait_for_durable(lsn);

        // Link new version to current head
        new_version->next_version.store(current_head, std::memory_order_relaxed);

        // Atomic CAS publication
        if (!page->head.compare_exchange_strong(current_head, new_version,
                                                std::memory_order_acq_rel,
                                                std::memory_order_acquire)) {
            // Conflict occurred during WAL persistence phase; abort & clean up
            ::free(new_version);
            epoch_mgr_.exit_critical_section(tid);
            return false;
        }

        // Retire replaced version into Epoch Garbage Collector
        epoch_mgr_.retire_version(current_head);
        epoch_mgr_.try_advance_epoch();

        epoch_mgr_.exit_critical_section(tid);
        return true;
    }

    uint64_t get_latest_timestamp() const {
        return global_ts_.load(std::memory_order_acquire);
    }
};

// ============================================================================
// Multi-Threaded Stress Test Verification Harness
// ============================================================================

int main() {
    std::cout << "Starting High-Throughput MVCC & io_uring WAL Engine..." << std::endl;

    const char* wal_file = "/tmp/mvcc_engine.wal";
    const size_t NUM_PAGES = 128;
    const size_t NUM_WORKERS = 8;
    const size_t OPS_PER_THREAD = 2000;

    auto engine = std::make_unique<MvccEngine>(NUM_PAGES, wal_file);
    std::vector<std::thread> workers;
    std::atomic<uint64_t> total_commits{0};
    std::atomic<uint64_t> total_aborts{0};

    auto start_time = std::chrono::high_resolution_clock::now();

    for (size_t t = 0; t < NUM_WORKERS; ++t) {
        workers.emplace_back([&, t]() {
            size_t tid = engine->register_worker();
            uint8_t buffer[PAGE_SIZE];

            for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
                uint64_t page_id = (t * 17 + i) % NUM_PAGES;
                uint64_t read_ts = engine->get_latest_timestamp();

                // Snapshot Read
                if (engine->read_page(tid, page_id, read_ts, buffer)) {
                    // Modify buffer
                    buffer[0] = static_cast<uint8_t>(tid);
                    buffer[1] = static_cast<uint8_t>(i & 0xFF);

                    // OCC Write
                    if (engine->update_page(tid, page_id, read_ts, buffer, PAGE_SIZE)) {
                        total_commits.fetch_add(1, std::memory_order_relaxed);
                    } else {
                        total_aborts.fetch_add(1, std::memory_order_relaxed);
                    }
                }
            }

            engine->unregister_worker(tid);
        });
    }

    for (auto& w : workers) {
        w.join();
    }

    auto end_time = std::chrono::high_resolution_clock::now();
    double duration = std::chrono::duration<double>(end_time - start_time).count();

    std::cout << "Execution complete in: " << duration << " seconds" << std::endl;
    std::cout << "Committed TXNs: " << total_commits.load() << std::endl;
    std::cout << "Aborted TXNs (OCC Conflicts): " << total_aborts.load() << std::endl;
    std::cout << "Throughput: " << (total_commits.load() / duration) << " durable updates/sec" << std::endl;

    ::unlink(wal_file);
    return 0;
}
