// ============================================================================
// Epoch-Based Reclamation (EBR) System
// ============================================================================
namespace ebr {

constexpr size_t NUM_EPOCHS = 3;
constexpr size_t RETIRE_THRESHOLD = 64;

struct alignas(CACHELINE_SIZE) ThreadDescriptor {
    std::atomic<bool> active{false};
    std::atomic<uint64_t> local_epoch{0};
    ThreadDescriptor* next{nullptr};

    // Retirement queues: 3 buckets for epochs 0, 1, 2
    std::vector<std::pair<void*, void(*)(void*)>> retire_lists[NUM_EPOCHS];
    size_t total_retired_count{0};
};

class EpochManager {
private:
    alignas(CACHELINE_SIZE) std::atomic<uint64_t> global_epoch_{0};
    alignas(CACHELINE_SIZE) std::atomic<ThreadDescriptor*> global_descriptors_{nullptr};

public:
    static EpochManager& instance() {
        static EpochManager mgr;
        return mgr;
    }

    void register_thread(ThreadDescriptor& desc) {
        ThreadDescriptor* old_head = global_descriptors_.load(std::memory_order_relaxed);
        do {
            desc.next = old_head;
        } while (!global_descriptors_.compare_exchange_weak(
            old_head, &desc, std::memory_order_release, std::memory_order_relaxed));
    }

    void enter(ThreadDescriptor& desc) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        desc.local_epoch.store(cur_epoch, std::memory_order_relaxed);
        // Acquire-Release barrier to ensure local active flag is visible before reading payload
        desc.active.store(true, std::memory_order_seq_cst);
    }

    void exit(ThreadDescriptor& desc) {
        // Reset active flag
        desc.active.store(false, std::memory_order_release);
        if (desc.total_retired_count >= RETIRE_THRESHOLD) {
            try_advance_and_reclaim(desc);
        }
    }

    template <typename T>
    void retire(ThreadDescriptor& desc, T* ptr) {
        if (!ptr) return;
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed) % NUM_EPOCHS;
        desc.retire_lists[cur_epoch].push_back({
            static_cast<void*>(ptr),
            [](void* p) { delete static_cast<T*>(p); }
        });
        desc.total_retired_count++;
    }

    void try_advance_and_reclaim(ThreadDescriptor& desc) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_acquire);

        // Scan all registered threads to verify if everyone caught up to cur_epoch
        ThreadDescriptor* curr = global_descriptors_.load(std::memory_order_acquire);
        bool can_advance = true;

        while (curr != nullptr) {
            if (curr->active.load(std::memory_order_acquire)) {
                if (curr->local_epoch.load(std::memory_order_relaxed) != cur_epoch) {
                    can_advance = false;
                    break;
                }
            }
            curr = curr->next;
        }

        if (can_advance) {
            // Attempt to monotonically advance the global epoch
            if (global_epoch_.compare_exchange_strong(cur_epoch, cur_epoch + 1,
                                                      std::memory_order_acq_rel,
                                                      std::memory_order_relaxed)) {
                cur_epoch++;
            }
        }

        // Safe epoch to reclaim is (cur_epoch + 1) % 3 (i.e. two ticks behind current global epoch)
        size_t safe_reclaim_epoch = (cur_epoch + 1) % NUM_EPOCHS;
        auto& list = desc.retire_lists[safe_reclaim_epoch];
        if (!list.empty()) {
            for (auto& item : list) {
                item.second(item.first); // Call deleter
            }
            desc.total_retired_count -= list.size();
            list.clear();
        }
    }

    ~EpochManager() {
        // Final cleanup of remaining allocations
        ThreadDescriptor* curr = global_descriptors_.load(std::memory_order_acquire);
        while (curr != nullptr) {
            for (size_t e = 0; e < NUM_EPOCHS; ++e) {
                for (auto& item : curr->retire_lists[e]) {
                    item.second(item.first);
                }
                curr->retire_lists[e].clear();
            }
            curr = curr->next;
        }
    }
};

thread_local ThreadDescriptor t_desc;
thread_local bool t_registered = false;

inline void ensure_registered() {
    if (!t_registered) {
        EpochManager::instance().register_thread(t_desc);
        t_registered = true;
    }
}

class EpochGuard {
public:
    EpochGuard() {
        ensure_registered();
        EpochManager::instance().enter(t_desc);
    }
    ~EpochGuard() {
        EpochManager::instance().exit(t_desc);
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

template <typename T>
inline void retire_node(T* ptr) {
    EpochManager::instance().retire(t_desc, ptr);
}

} // namespace ebr

// ============================================================================
// MVCC SkipList Node Structures
// ============================================================================

template <typename Value>
struct VersionNode {
    uint64_t commit_ts;
    bool is_tombstone;
    std::optional<Value> value;
    std::atomic<VersionNode*> next_version{nullptr};

    VersionNode(uint64_t ts, std::optional<Value> val, bool tombstone)
        : commit_ts(ts), is_tombstone(tombstone), value(std::move(val)), next_version(nullptr) {}
};

template <typename Key, typename Value>
struct SkipNode {
    Key key;
    size_t height;
    std::atomic<VersionNode<Value>*> version_head{nullptr};
    std::atomic<SkipNode*> forward[MAX_HEIGHT];

    SkipNode(Key k, size_t h) : key(std::move(k)), height(h) {
        for (size_t i = 0; i < MAX_HEIGHT; ++i) {
            forward[i].store(nullptr, std::memory_order_relaxed);
        }
    }
};

// ============================================================================
// Concurrent MVCC SkipList Implementation
// ============================================================================

template <typename Key, typename Value, typename Compare = std::less<Key>>
class MVCCSkipList {
public:
    using Node = SkipNode<Key, Value>;
    using VNode = VersionNode<Value>;

private:
    Compare comp_;
    Node* head_;

    bool key_less(const Key& a, const Key& b) const { return comp_(a, b); }
    bool key_equal(const Key& a, const Key& b) const { return !comp_(a, b) && !comp_(b, a); }

    // Helper: search predecessors and successors across all levels
    void find_position(const Key& key,
                       std::array<Node*, MAX_HEIGHT>& preds,
                       std::array<Node*, MAX_HEIGHT>& succs) const {
        Node* curr = head_;
        for (int l = static_cast<int>(MAX_HEIGHT) - 1; l >= 0; --l) {
            Node* next = curr->forward[l].load(std::memory_order_acquire);
            while (next != nullptr && key_less(next->key, key)) {
                curr = next;
                next = curr->forward[l].load(std::memory_order_acquire);
            }
            preds[l] = curr;
            succs[l] = next;
        }
    }

    // Atomic version prepend to a node's MVCC chain
    bool prepend_version(Node* node, uint64_t commit_ts, std::optional<Value> val, bool is_tombstone) {
        auto* new_vnode = new VNode(commit_ts, std::move(val), is_tombstone);
        VNode* cur_head = node->version_head.load(std::memory_order_acquire);

        while (true) {
            if (cur_head != nullptr && cur_head->commit_ts >= commit_ts) {
                // Monotonic timestamp violation (newer or equal write already linearized)
                delete new_vnode;
                return false;
            }
            new_vnode->next_version.store(cur_head, std::memory_order_relaxed);

            // Release memory order ensures the new version's payload is fully visible
            if (node->version_head.compare_exchange_weak(
                    cur_head, new_vnode,
                    std::memory_order_release,
                    std::memory_order_acquire)) {
                return true;
            }
        }
    }

public:
    explicit MVCCSkipList(Compare comp = Compare()) : comp_(comp) {
        // Head node initialized with empty/default key and full height
        head_ = new Node(Key{}, MAX_HEIGHT);
    }

    ~MVCCSkipList() {
        Node* curr = head_;
        while (curr != nullptr) {
            Node* next = curr->forward[0].load(std::memory_order_relaxed);

            // Clean version chain
            VNode* vcurr = curr->version_head.load(std::memory_order_relaxed);
            while (vcurr != nullptr) {
                VNode* vnext = vcurr->next_version.load(std::memory_order_relaxed);
                delete vcurr;
                vcurr = vnext;
            }
            delete curr;
            curr = next;
        }
    }

    // Disallow copies
    MVCCSkipList(const MVCCSkipList&) = delete;
    MVCCSkipList& operator=(const MVCCSkipList&) = delete;

    // ------------------------------------------------------------------------
    // Point Operations
    // ------------------------------------------------------------------------

    bool insert(const Key& key, Value value, uint64_t commit_ts) {
        ebr::EpochGuard guard;
        while (true) {
            std::array<Node*, MAX_HEIGHT> preds;
            std::array<Node*, MAX_HEIGHT> succs;
            find_position(key, preds, succs);

            Node* target = succs[0];
            if (target != nullptr && key_equal(target->key, key)) {
                // Key exists: atomically prepend to version chain
                return prepend_version(target, commit_ts, std::move(value), false);
            }

            // Key does not exist: create new node and insert into index
            size_t height = t_rng.random_height();
            Node* new_node = new Node(key, height);

            // Create initial version node
            auto* vnode = new VNode(commit_ts, std::move(value), false);
            new_node->version_head.store(vnode, std::memory_order_relaxed);

            // Connect lower levels optimistically
            for (size_t l = 0; l < height; ++l) {
                new_node->forward[l].store(succs[l], std::memory_order_relaxed);
            }

            // Linearization point: atomic link at Level 0
            if (!preds[0]->forward[0].compare_exchange_strong(
                    succs[0], new_node,
                    std::memory_order_release,
                    std::memory_order_acquire)) {
                delete vnode;
                delete new_node;
                continue; // CAS failed; retry search
            }

            // Splice remaining higher levels
            for (size_t l = 1; l < height; ++l) {
                while (true) {
                    Node* pred = preds[l];
                    Node* succ = succs[l];
                    new_node->forward[l].store(succ, std::memory_order_relaxed);
                    if (pred->forward[l].compare_exchange_weak(
                            succ, new_node,
                            std::memory_order_release,
                            std::memory_order_acquire)) {
                        break;
                    }
                    // Re-search level position on contention
                    find_position(key, preds, succs);
                }
            }
            return true;
        }
    }

    bool remove(const Key& key, uint64_t commit_ts) {
        ebr::EpochGuard guard;
        while (true) {
            std::array<Node*, MAX_HEIGHT> preds;
            std::array<Node*, MAX_HEIGHT> succs;
            find_position(key, preds, succs);

            Node* target = succs[0];
            if (target == nullptr || !key_equal(target->key, key)) {
                // Key does not exist: create a node with tombstone version to record delete
                size_t height = t_rng.random_height();
                Node* new_node = new Node(key, height);
                auto* vnode = new VNode(commit_ts, std::nullopt, true);
                new_node->version_head.store(vnode, std::memory_order_relaxed);

                for (size_t l = 0; l < height; ++l) {
                    new_node->forward[l].store(succs[l], std::memory_order_relaxed);
                }

                if (!preds[0]->forward[0].compare_exchange_strong(
                        succs[0], new_node,
                        std::memory_order_release,
                        std::memory_order_acquire)) {
                    delete vnode;
                    delete new_node;
                    continue;
                }
                for (size_t l = 1; l < height; ++l) {
                    while (true) {
                        Node* pred = preds[l];
                        Node* succ = succs[l];
                        new_node->forward[l].store(succ, std::memory_order_relaxed);
                        if (pred->forward[l].compare_exchange_weak(
                                succ, new_node,
                                std::memory_order_release,
                                std::memory_order_acquire)) {
                            break;
                        }
                        find_position(key, preds, succs);
                    }
                }
                return true;
            }

            // Append tombstone to existing key version chain
            return prepend_version(target, commit_ts, std::nullopt, true);
        }
    }

    std::optional<Value> get(const Key& key, uint64_t read_ts) const {
        ebr::EpochGuard guard; // Protects traversed nodes from physical reclamation

        Node* curr = head_;
        for (int l = static_cast<int>(MAX_HEIGHT) - 1; l >= 0; --l) {
            Node* next = curr->forward[l].load(std::memory_order_acquire);
            while (next != nullptr && key_less(next->key, key)) {
                curr = next;
                next = curr->forward[l].load(std::memory_order_acquire);
            }
        }

        Node* target = curr->forward[0].load(std::memory_order_acquire);
        if (target == nullptr || !key_equal(target->key, key)) {
            return std::nullopt;
        }

        // Traverse version chain in descending commit_ts order
        VNode* vcurr = target->version_head.load(std::memory_order_acquire);
        while (vcurr != nullptr) {
            if (vcurr->commit_ts <= read_ts) {
                if (vcurr->is_tombstone) {
                    return std::nullopt; // Logically deleted at this snapshot
                }
                return vcurr->value;
            }
            vcurr = vcurr->next_version.load(std::memory_order_acquire);
        }
        return std::nullopt;
    }

    // ------------------------------------------------------------------------
    // Snapshot Range Scan
    // ------------------------------------------------------------------------

    std::vector<std::pair<Key, Value>> scan(const Key& start_key,
                                            const Key& end_key,
                                            uint64_t read_ts,
                                            size_t limit = SIZE_MAX) const {
        ebr::EpochGuard guard;
        std::vector<std::pair<Key, Value>> result;
        result.reserve(limit < 1024 ? limit : 1024);

        Node* curr = head_;
        // Descend to locate lower bound
        for (int l = static_cast<int>(MAX_HEIGHT) - 1; l >= 0; --l) {
            Node* next = curr->forward[l].load(std::memory_order_acquire);
            while (next != nullptr && key_less(next->key, start_key)) {
                curr = next;
                next = curr->forward[l].load(std::memory_order_acquire);
            }
        }

        curr = curr->forward[0].load(std::memory_order_acquire);

        // Linear scan across Level 0
        while (curr != nullptr && result.size() < limit) {
            if (key_less(end_key, curr->key)) {
                break; // Exceeded upper bound
            }

            // Find valid snapshot version
            VNode* vcurr = curr->version_head.load(std::memory_order_acquire);
            while (vcurr != nullptr) {
                if (vcurr->commit_ts <= read_ts) {
                    if (!vcurr->is_tombstone && vcurr->value.has_value()) {
                        result.emplace_back(curr->key, *vcurr->value);
                    }
                    break;
                }
                vcurr = vcurr->next_version.load(std::memory_order_acquire);
            }

            curr = curr->forward[0].load(std::memory_order_acquire);
        }

        return result;
    }
};

