// ============================================================================
// 1. EPOCH-BASED MEMORY RECLAMATION (EBR)
// ============================================================================

class EpochManager {
public:
    static constexpr size_t NUM_EPOCHS = 3;
    static constexpr size_t MAX_THREADS = 128;
    static constexpr uint64_t INACTIVE_EPOCH = std::numeric_limits<uint64_t>::max();

    struct alignas(std::hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{INACTIVE_EPOCH};
        std::atomic<bool> active{false};
    };

    struct RetiredNode {
        void* ptr;
        void (*deleter)(void*);
        RetiredNode* next;
    };

private:
    alignas(std::hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_{0};
    alignas(std::hardware_destructive_interference_size) std::array<ThreadControlBlock, MAX_THREADS> tcbs_;

    // Per-epoch retired lists (protected by reclaimer lock or local thread staging)
    alignas(std::hardware_destructive_interference_size) std::array<std::atomic<RetiredNode*>, NUM_EPOCHS> retired_lists_{};

public:
    EpochManager() {
        for (size_t i = 0; i < NUM_EPOCHS; ++i) {
            retired_lists_[i].store(nullptr, std::memory_order_relaxed);
        }
    }

    ~EpochManager() {
        // Drain all remaining memory allocations across epochs
        for (size_t i = 0; i < NUM_EPOCHS; ++i) {
            RetiredNode* curr = retired_lists_[i].exchange(nullptr, std::memory_order_relaxed);
            while (curr) {
                RetiredNode* next = curr->next;
                curr->deleter(curr->ptr);
                delete curr;
                curr = next;
            }
        }
    }

    size_t register_thread() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (tcbs_[i].active.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
                return i;
            }
        }
        throw std::runtime_error("Exceeded maximum thread capacity for EpochManager");
    }

    void unregister_thread(size_t tid) {
        assert(tid < MAX_THREADS);
        tcbs_[tid].local_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
        tcbs_[tid].active.store(false, std::memory_order_release);
    }

    inline void enter(size_t tid) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        tcbs_[tid].local_epoch.store(cur_epoch, std::memory_order_seq_cst);
    }

    inline void exit(size_t tid) {
        tcbs_[tid].local_epoch.store(INACTIVE_EPOCH, std::memory_order_seq_cst);
    }

    template <typename T>
    void retire(T* ptr) {
        if (!ptr) return;
        auto* node = new RetiredNode{
            .ptr = static_cast<void*>(ptr),
            .deleter = [](void* p) { delete static_cast<T*>(p); },
            .next = nullptr
        };
        uint64_t e = global_epoch_.load(std::memory_order_relaxed) % NUM_EPOCHS;

        RetiredNode* head = retired_lists_[e].load(std::memory_order_relaxed);
        do {
            node->next = head;
        } while (!retired_lists_[e].compare_exchange_weak(
            head, node, std::memory_order_release, std::memory_order_relaxed));
    }

    void try_advance_and_reclaim() {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);

        // Ensure no active thread is in the older epochs
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (tcbs_[i].active.load(std::memory_order_acquire)) {
                uint64_t t_epoch = tcbs_[i].local_epoch.load(std::memory_order_seq_cst);
                if (t_epoch != INACTIVE_EPOCH && t_epoch < cur_epoch) {
                    return; // Thread still holding an older epoch
                }
            }
        }

        // Advance global epoch
        if (global_epoch_.compare_exchange_strong(cur_epoch, cur_epoch + 1, std::memory_order_seq_cst)) {
            // Reclaim (cur_epoch + 2) % 3 which is now strictly 2 cycles behind
            size_t reclaim_idx = (cur_epoch + 1) % NUM_EPOCHS;
            RetiredNode* to_free = retired_lists_[reclaim_idx].exchange(nullptr, std::memory_order_acq_rel);

            while (to_free) {
                RetiredNode* next = to_free->next;
                to_free->deleter(to_free->ptr);
                delete to_free;
                to_free = next;
            }
        }
    }
};

class EpochGuard {
    EpochManager& mgr_;
    size_t tid_;
public:
    EpochGuard(EpochManager& mgr, size_t tid) : mgr_(mgr), tid_(tid) {
        mgr_.enter(tid_);
    }
    ~EpochGuard() {
        mgr_.exit(tid_);
    }
};

// ============================================================================
// 2. TAGGED POINTERS & INDIRECTION MAPPING TABLE
// ============================================================================

using PageID = uint64_t;
using LSN = uint64_t;
using TxnTimestamp = uint64_t;

enum class NodeType : uint8_t {
    BASE_PAGE = 0,
    INSERT_DELTA = 1,
    DELETE_DELTA = 2,
    SPLIT_DELTA = 3,
    INDEX_NODE = 4
};

struct Node {
    NodeType type;
    Node* next;
    alignas(16) uint8_t padding[8];
    virtual ~Node() = default;
};

struct TaggedPointer {
    uintptr_t raw;

    static constexpr uintptr_t PTR_MASK = 0x0000FFFFFFFFFFFFULL;
    static constexpr uintptr_t TAG_MASK = 0xFFFF000000000000ULL;
    static constexpr uintptr_t CHAIN_LEN_SHIFT = 48;

    TaggedPointer() noexcept : raw(0) {}
    TaggedPointer(Node* ptr, uint16_t chain_len) noexcept {
        raw = (reinterpret_cast<uintptr_t>(ptr) & PTR_MASK) | 
              (static_cast<uintptr_t>(chain_len) << CHAIN_LEN_SHIFT);
    }

    [[nodiscard]] Node* ptr() const noexcept {
        return reinterpret_cast<Node*>(raw & PTR_MASK);
    }

    [[nodiscard]] uint16_t chain_len() const noexcept {
        return static_cast<uint16_t>((raw & TAG_MASK) >> CHAIN_LEN_SHIFT);
    }

    bool operator==(const TaggedPointer& other) const noexcept = default;
};

class MappingTable {
public:
    static constexpr size_t MAX_PAGES = 1048576;

    struct alignas(std::hardware_destructive_interference_size) Entry {
        std::atomic<TaggedPointer> ptr{TaggedPointer(nullptr, 0)};
    };

private:
    std::vector<Entry> table_;
    std::atomic<PageID> next_page_id_{1};

public:
    MappingTable() : table_(MAX_PAGES) {}

    PageID allocate_page_id() {
        return next_page_id_.fetch_add(1, std::memory_order_relaxed);
    }

    TaggedPointer get(PageID pid) const {
        assert(pid < MAX_PAGES);
        return table_[pid].ptr.load(std::memory_order_acquire);
    }

    bool compare_exchange(PageID pid, TaggedPointer& expected, TaggedPointer desired) {
        assert(pid < MAX_PAGES);
        return table_[pid].ptr.compare_exchange_strong(
            expected, desired,
            std::memory_order_acq_rel,
            std::memory_order_acquire);
    }

    void set(PageID pid, TaggedPointer desired) {
        assert(pid < MAX_PAGES);
        table_[pid].ptr.store(desired, std::memory_order_release);
    }
};

// ============================================================================
// 3. MVCC, BW-TREE DELTAS & BASE PAGES
// ============================================================================

struct Record {
    uint64_t key;
    uint64_t val;
    TxnTimestamp commit_ts;
    bool is_deleted;
};

struct BasePage : public Node {
    static constexpr size_t CAPACITY = 16;
    size_t count{0};
    Record records[CAPACITY];
    PageID high_sibling{0};
    uint64_t low_key{0};
    uint64_t high_key{std::numeric_limits<uint64_t>::max()};

    BasePage() {
        type = NodeType::BASE_PAGE;
        next = nullptr;
    }
};

struct InsertDeltaNode : public Node {
    Record record;
    InsertDeltaNode(Record rec, Node* prev) {
        type = NodeType::INSERT_DELTA;
        record = rec;
        next = prev;
    }
};

struct DeleteDeltaNode : public Node {
    uint64_t key;
    TxnTimestamp commit_ts;
    DeleteDeltaNode(uint64_t k, TxnTimestamp ts, Node* prev) {
        type = NodeType::DELETE_DELTA;
        key = k;
        commit_ts = ts;
        next = prev;
    }
};

struct SplitDeltaNode : public Node {
    uint64_t split_key;
    PageID right_sibling;
    SplitDeltaNode(uint64_t skey, PageID right_pid, Node* prev) {
        type = NodeType::SPLIT_DELTA;
        split_key = skey;
        right_sibling = right_pid;
        next = prev;
    }
};

struct IndexNode : public Node {
    static constexpr size_t CAPACITY = 16;
    size_t count{0};
    uint64_t keys[CAPACITY];
    PageID children[CAPACITY + 1];

    IndexNode() {
        type = NodeType::INDEX_NODE;
        next = nullptr;
    }
};

// ============================================================================
// 4. ASYNCHRONOUS IO_URING WAL PIPELINE & GROUP COMMIT
// ============================================================================

struct WalRecord {
    uint32_t payload_len;
    uint32_t checksum;
    TxnTimestamp commit_ts;
    uint64_t key;
    uint64_t val;
    uint8_t op_type; // 0 = insert, 1 = delete
    std::atomic<uint8_t> ready{0};
};

class alignas(std::hardware_destructive_interference_size) IoUringWal {
public:
    static constexpr size_t BUFFER_SIZE = 16 * 1024 * 1024; // 16 MB Ring Buffer
    static constexpr size_t SECTOR_SIZE = 512;
    static constexpr size_t QUEUE_DEPTH = 256;

private:
    int wal_fd_{-1};
    struct io_uring ring_{};
    uint8_t* aligned_buffer_{nullptr};

    alignas(std::hardware_destructive_interference_size) std::atomic<uint64_t> write_tail_{0};
    alignas(std::hardware_destructive_interference_size) std::atomic<uint64_t> flush_head_{0};
    alignas(std::hardware_destructive_interference_size) std::atomic<uint64_t> flushed_lsn_{0};

    std::atomic<bool> running_{true};
    std::thread flush_thread_;

    struct iovec iov_{};

public:
    explicit IoUringWal(const char* wal_path) {
        wal_fd_ = open(wal_path, O_RDWR | O_CREAT | O_DIRECT, 0644);
        if (wal_fd_ < 0) {
            throw std::runtime_error("Failed to open WAL file with O_DIRECT");
        }

        // Align circular arena to 4096-byte boundary for O_DIRECT writes
        int ret = posix_memalign(reinterpret_cast<void**>(&aligned_buffer_), 4096, BUFFER_SIZE);
        if (ret != 0) {
            throw std::bad_alloc();
        }
        std::memset(aligned_buffer_, 0, BUFFER_SIZE);

        struct io_uring_params params{};
        params.flags = IORING_SETUP_SQPOLL;
        params.sq_thread_idle = 2000;

        ret = io_uring_queue_init_params(QUEUE_DEPTH, &ring_, &params);
        if (ret < 0) {
            // Fallback without SQPOLL if permissions/features lack SQPOLL support
            ret = io_uring_queue_init(QUEUE_DEPTH, &ring_, 0);
            if (ret < 0) {
                throw std::runtime_error("Failed to initialize io_uring");
            }
        }

        iov_.iov_base = aligned_buffer_;
        iov_.iov_len = BUFFER_SIZE;
        ret = io_uring_register_buffers(&ring_, &iov_, 1);
        if (ret < 0) {
            throw std::runtime_error("Failed to register fixed buffers for io_uring");
        }

        flush_thread_ = std::thread(&IoUringWal::flusher_loop, this);
    }

    ~IoUringWal() {
        running_.store(false, std::memory_order_release);
        if (flush_thread_.joinable()) {
            flush_thread_.join();
        }
        io_uring_unregister_buffers(&ring_);
        io_uring_queue_exit(&ring_);
        if (wal_fd_ >= 0) {
            close(wal_fd_);
        }
        free(aligned_buffer_);
    }

    LSN append(uint64_t key, uint64_t val, TxnTimestamp ts, uint8_t op_type) {
        size_t record_len = sizeof(WalRecord);
        uint64_t pos = write_tail_.fetch_add(record_len, std::memory_order_relaxed);

        size_t offset = pos % BUFFER_SIZE;
        // Check if append would overflow past the physical end of the circular buffer
        if (offset + record_len > BUFFER_SIZE) {
            // Write a padding marker record and realign to 0
            size_t pad_size = BUFFER_SIZE - offset;
            auto* pad_rec = reinterpret_cast<WalRecord*>(aligned_buffer_ + offset);
            pad_rec->payload_len = static_cast<uint32_t>(pad_size);
            pad_rec->op_type = 0xFF; // Padding marker
            pad_rec->ready.store(1, std::memory_order_release);

            pos = write_tail_.fetch_add(BUFFER_SIZE - offset + record_len, std::memory_order_relaxed);
            offset = 0;
        }

        auto* rec = reinterpret_cast<WalRecord*>(aligned_buffer_ + offset);
        rec->payload_len = static_cast<uint32_t>(record_len);
        rec->commit_ts = ts;
        rec->key = key;
        rec->val = val;
        rec->op_type = op_type;
        rec->checksum = static_cast<uint32_t>(key ^ val ^ ts);

        rec->ready.store(1, std::memory_order_release);
        return pos + record_len;
    }

    void wait_flush(LSN lsn) {
        while (flushed_lsn_.load(std::memory_order_acquire) < lsn) {
            std::this_thread::yield();
        }
    }

private:
    void flusher_loop() {
        uint64_t current_file_offset = 0;

        while (running_.load(std::memory_order_acquire)) {
            uint64_t head = flush_head_.load(std::memory_order_relaxed);
            uint64_t tail = write_tail_.load(std::memory_order_acquire);

            if (head >= tail) {
                std::this_thread::yield();
                continue;
            }

            size_t bytes_to_write = tail - head;
            size_t head_offset = head % BUFFER_SIZE;

            // Wait for records in the current window to become ready
            size_t scan = head;
            bool window_ready = true;
            while (scan < tail) {
                size_t off = scan % BUFFER_SIZE;
                auto* rec = reinterpret_cast<WalRecord*>(aligned_buffer_ + off);
                if (rec->ready.load(std::memory_order_acquire) == 0) {
                    window_ready = false;
                    break;
                }
                if (rec->op_type == 0xFF) {
                    scan += (BUFFER_SIZE - off);
                } else {
                    scan += rec->payload_len;
                }
            }

            if (!window_ready && scan == head) {
                std::this_thread::yield();
                continue;
            }

            bytes_to_write = scan - head;
            if (bytes_to_write == 0) continue;

            // Align to 512-byte sector for Direct I/O
            size_t aligned_len = (bytes_to_write + SECTOR_SIZE - 1) & ~(SECTOR_SIZE - 1);
            if (head_offset + aligned_len > BUFFER_SIZE) {
                aligned_len = BUFFER_SIZE - head_offset;
            }

            struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
            if (!sqe) {
                io_uring_submit(&ring_);
                continue;
            }

            io_uring_prep_write_fixed(sqe, wal_fd_, aligned_buffer_ + head_offset, 
                                      aligned_len, current_file_offset, 0);
            io_uring_sqe_set_data(sqe, reinterpret_cast<void*>(head + bytes_to_write));
            io_uring_submit(&ring_);

            struct io_uring_cqe* cqe;
            int ret = io_uring_wait_cqe(&ring_, &cqe);
            if (ret >= 0) {
                uint64_t completed_lsn = reinterpret_cast<uint64_t>(io_uring_cqe_get_data(cqe));
                io_uring_cqe_seen(&ring_, cqe);

                current_file_offset += aligned_len;
                flush_head_.store(head + bytes_to_write, std::memory_order_release);
                flushed_lsn_.store(completed_lsn, std::memory_order_release);
            }
        }
    }
};

// ============================================================================
// 5. CONCURRENT TRANSACTION MANAGER (MVCC - SNAPSHOT ISOLATION)
// ============================================================================

class TxnManager {
private:
    alignas(std::hardware_destructive_interference_size) std::atomic<TxnTimestamp> global_timestamp_{1};

public:
    TxnTimestamp begin_transaction() {
        return global_timestamp_.load(std::memory_order_relaxed);
    }

    TxnTimestamp commit_transaction() {
        return global_timestamp_.fetch_add(1, std::memory_order_acq_rel) + 1;
    }
};

// ============================================================================
// 6. BW-TREE CORE ENGINE
// ============================================================================

class BwTreeEngine {
public:
    static constexpr size_t MAX_DELTA_CHAIN = 8;

private:
    MappingTable mapping_table_;
    EpochManager epoch_mgr_;
    IoUringWal wal_;
    TxnManager txn_mgr_;
    PageID root_id_{0};

public:
    explicit BwTreeEngine(const char* wal_path) : wal_(wal_path) {
        root_id_ = mapping_table.allocate_page_id();
        auto* base = new BasePage();
        mapping_table_.set(root_id_, TaggedPointer(base, 0));
    }

    ~BwTreeEngine() = default;

    EpochManager& get_epoch_manager() { return epoch_mgr_; }
    TxnManager& get_txn_manager() { return txn_mgr_; }

    std::optional<uint64_t> get(uint64_t key, TxnTimestamp read_ts, size_t tid) {
        EpochGuard guard(epoch_mgr_, tid);

        PageID cur_pid = root_id_;
        while (true) {
            TaggedPointer tp = mapping_table_.get(cur_pid);
            Node* head = tp.ptr();

            // Check if page needs consolidation
            if (tp.chain_len() >= MAX_DELTA_CHAIN) {
                consolidate_page(cur_pid, tp, tid);
            }

            // Traverse delta chain & evaluate MVCC visibility
            Node* curr = head;
            bool found_entry = false;
            std::optional<uint64_t> result = std::nullopt;

            while (curr) {
                if (curr->type == NodeType::INSERT_DELTA) {
                    auto* idn = static_cast<InsertDeltaNode*>(curr);
                    if (idn->record.key == key) {
                        if (idn->record.commit_ts <= read_ts) {
                            return idn->record.val;
                        }
                    }
                } else if (curr->type == NodeType::DELETE_DELTA) {
                    auto* ddn = static_cast<DeleteDeltaNode*>(curr);
                    if (ddn->key == key) {
                        if (ddn->commit_ts <= read_ts) {
                            return std::nullopt;
                        }
                    }
                } else if (curr->type == NodeType::SPLIT_DELTA) {
                    auto* sdn = static_cast<SplitDeltaNode*>(curr);
                    if (key >= sdn->split_key) {
                        cur_pid = sdn->right_sibling;
                        found_entry = true;
                        break; // Forward down sibling path
                    }
                } else if (curr->type == NodeType::INDEX_NODE) {
                    auto* in = static_cast<IndexNode*>(curr);
                    cur_pid = in->children[0];
                    for (size_t i = 0; i < in->count; ++i) {
                        if (key >= in->keys[i]) {
                            cur_pid = in->children[i + 1];
                        } else {
                            break;
                        }
                    }
                    found_entry = true;
                    break;
                } else if (curr->type == NodeType::BASE_PAGE) {
                    auto* bp = static_cast<BasePage*>(curr);
                    if (key >= bp->high_key && bp->high_sibling != 0) {
                        cur_pid = bp->high_sibling;
                        found_entry = true;
                        break;
                    }
                    for (size_t i = 0; i < bp->count; ++i) {
                        if (bp->records[i].key == key) {
                            if (bp->records[i].commit_ts <= read_ts) {
                                if (!bp->records[i].is_deleted) {
                                    result = bp->records[i].val;
                                }
                            }
                            return result;
                        }
                    }
                    return std::nullopt;
                }
                curr = curr->next;
            }

            if (!found_entry) {
                return result;
            }
        }
    }

    bool put(uint64_t key, uint64_t val, size_t tid) {
        EpochGuard guard(epoch_mgr_, tid);

        TxnTimestamp commit_ts = txn_mgr_.commit_transaction();
        LSN lsn = wal_.append(key, val, commit_ts, 0);

        PageID target_pid = find_leaf_page(key);

        while (true) {
            TaggedPointer tp = mapping_table_.get(target_pid);

            // WW-Conflict check against newest uncommitted / younger delta
            Node* head = tp.ptr();
            if (head && head->type == NodeType::INSERT_DELTA) {
                auto* idn = static_cast<InsertDeltaNode*>(head);
                if (idn->record.key == key && idn->record.commit_ts > commit_ts) {
                    return false; // First-Committer-Wins abort
                }
            }

            auto* new_node = new InsertDeltaNode(
                Record{.key = key, .val = val, .commit_ts = commit_ts, .is_deleted = false},
                head
            );

            TaggedPointer desired(new_node, tp.chain_len() + 1);

            if (mapping_table_.compare_exchange(target_pid, tp, desired)) {
                if (desired.chain_len() >= MAX_DELTA_CHAIN) {
                    consolidate_page(target_pid, desired, tid);
                }
                wal_.wait_flush(lsn);
                return true;
            } else {
                delete new_node; // CAS race failed, retry loop
            }
        }
    }

private:
    PageID find_leaf_page(uint64_t key) {
        PageID cur_pid = root_id_;
        while (true) {
            TaggedPointer tp = mapping_table_.get(cur_pid);
            Node* curr = tp.ptr();

            if (curr->type == NodeType::INDEX_NODE) {
                auto* in = static_cast<IndexNode*>(curr);
                PageID next_pid = in->children[0];
                for (size_t i = 0; i < in->count; ++i) {
                    if (key >= in->keys[i]) {
                        next_pid = in->children[i + 1];
                    } else {
                        break;
                    }
                }
                cur_pid = next_pid;
            } else if (curr->type == NodeType::SPLIT_DELTA) {
                auto* sdn = static_cast<SplitDeltaNode*>(curr);
                if (key >= sdn->split_key) {
                    cur_pid = sdn->right_sibling;
                } else {
                    return cur_pid;
                }
            } else {
                return cur_pid;
            }
        }
    }

    void consolidate_page(PageID pid, TaggedPointer expected_tp, size_t tid) {
        Node* head = expected_tp.ptr();
        if (!head || head->type == NodeType::INDEX_NODE) return;

        auto* consolidated = new BasePage();
        std::vector<Record> flattened;
        std::vector<Node*> chain_nodes;

        Node* curr = head;
        while (curr) {
            chain_nodes.push_back(curr);
            if (curr->type == NodeType::INSERT_DELTA) {
                auto* idn = static_cast<InsertDeltaNode*>(curr);
                flattened.push_back(idn->record);
            } else if (curr->type == NodeType::DELETE_DELTA) {
                auto* ddn = static_cast<DeleteDeltaNode*>(curr);
                flattened.push_back(Record{
                    .key = ddn->key,
                    .val = 0,
                    .commit_ts = ddn->commit_ts,
                    .is_deleted = true
                });
            } else if (curr->type == NodeType::BASE_PAGE) {
                auto* bp = static_cast<BasePage*>(curr);
                consolidated->high_sibling = bp->high_sibling;
                consolidated->low_key = bp->low_key;
                consolidated->high_key = bp->high_key;
                for (size_t i = 0; i < bp->count; ++i) {
                    flattened.push_back(bp->records[i]);
                }
                break;
            }
            curr = curr->next;
        }

        // Sort descending by commit_ts so newest keys win deduplication
        std::stable_sort(flattened.begin(), flattened.end(), [](const Record& a, const Record& b) {
            return a.commit_ts > b.commit_ts;
        });

        std::vector<Record> final_records;
        for (const auto& rec : flattened) {
            bool exists = false;
            for (const auto& f : final_records) {
                if (f.key == rec.key) {
                    exists = true;
                    break;
                }
            }
            if (!exists && !rec.is_deleted) {
                final_records.push_back(rec);
            }
        }

        // Sort final ascending by key for BasePage linear search
        std::sort(final_records.begin(), final_records.end(), [](const Record& a, const Record& b) {
            return a.key < b.key;
        });

        // Handle page split if base page exceeds capacity threshold
        if (final_records.size() > BasePage::CAPACITY) {
            execute_page_split(pid, expected_tp, final_records, chain_nodes, tid);
            delete consolidated;
            return;
        }

        consolidated->count = final_records.size();
        for (size_t i = 0; i < final_records.size(); ++i) {
            consolidated->records[i] = final_records[i];
        }

        TaggedPointer desired(consolidated, 0);

        if (mapping_table_.compare_exchange(pid, expected_tp, desired)) {
            // Enqueue all old delta nodes and obsolete BasePage to EBR
            for (Node* node : chain_nodes) {
                epoch_mgr_.retire(node);
            }
        } else {
            delete consolidated; // Lost race to another worker/delta append
        }
    }

    void execute_page_split(PageID left_pid, TaggedPointer expected_tp, 
                            const std::vector<Record>& records,
                            const std::vector<Node*>& retired_nodes, 
                            size_t tid) {
        size_t mid = records.size() / 2;
        uint64_t split_key = records[mid].key;

        PageID right_pid = mapping_table_.allocate_page_id();
        auto* right_base = new BasePage();
        right_base->count = records.size() - mid;
        for (size_t i = mid; i < records.size(); ++i) {
            right_base->records[i - mid] = records[i];
        }
        right_base->low_key = split_key;

        mapping_table_.set(right_pid, TaggedPointer(right_base, 0));

        // Step 1: Prepend SplitDeltaNode to the left page
        auto* sdn = new SplitDeltaNode(split_key, right_pid, expected_tp.ptr());
        TaggedPointer split_tp(sdn, expected_tp.chain_len() + 1);

        if (!mapping_table_.compare_exchange(left_pid, expected_tp, split_tp)) {
            delete sdn;
            delete right_base;
            return; // CAS race failed; let subsequent worker re-try compaction
        }

        // Step 2: Consolidate left page base page containing low records
        auto* left_base = new BasePage();
        left_base->count = mid;
        for (size_t i = 0; i < mid; ++i) {
            left_base->records[i] = records[i];
        }
        left_base->high_key = split_key;
        left_base->high_sibling = right_pid;

        TaggedPointer left_consolidated(left_base, 0);
        if (mapping_table_.compare_exchange(left_pid, split_tp, left_consolidated)) {
            for (Node* n : retired_nodes) {
                epoch_mgr_.retire(n);
            }
            epoch_mgr_.retire(sdn);
        } else {
            delete left_base;
        }
    }
};
```

