### 2.2 Epoch-Based Memory Reclamation (EBR) Subsystem

```cpp
// ============================================================================
// 2.2 LOCK-FREE EPOCH-BASED RECLAMATION (EBR)
// ============================================================================

struct alignas(std::hardware_destructive_interference_size) EpochNode {
    virtual ~EpochNode() = default;
};

class EpochManager {
public:
    static constexpr uint64_t EPOCH_INACTIVE = 0xFFFFFFFFFFFFFFFFULL;

    struct alignas(std::hardware_destructive_interference_size) ThreadDescriptor {
        std::atomic<uint64_t> local_epoch{EPOCH_INACTIVE};
        std::atomic<bool> in_use{false};
        std::vector<EpochNode*> retire_lists[3];
        size_t ops_since_gc{0};
    };

private:
    std::atomic<uint64_t> global_epoch_{0};
    std::array<ThreadDescriptor, MAX_THREADS> threads_{};

public:
    EpochManager() = default;

    ~EpochManager() {
        for (auto& td : threads_) {
            for (int e = 0; e < 3; ++e) {
                for (auto* node : td.retire_lists[e]) {
                    delete node;
                }
                td.retire_lists[e].clear();
            }
        }
    }

    size_t register_thread() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (threads_[i].in_use.compare_exchange_strong(expected, true, 
                    std::memory_order_acq_rel, std::memory_order_relaxed)) {
                return i;
            }
        }
        throw std::runtime_error("Exceeded maximum thread capacity in EpochManager");
    }

    void unregister_thread(size_t tid) {
        assert(tid < MAX_THREADS);
        quiesce(tid);
        threads_[tid].in_use.store(false, std::memory_order_release);
    }

    void enter_epoch(size_t tid) {
        // Load global epoch and set thread's local epoch
        uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed);
        threads_[tid].local_epoch.store(g_epoch, std::memory_order_seq_cst);
    }

    void exit_epoch(size_t tid) {
        threads_[tid].local_epoch.store(EPOCH_INACTIVE, std::memory_order_seq_cst);
        if (++threads_[tid].ops_since_gc >= 64) {
            threads_[tid].ops_since_gc = 0;
            attempt_gc(tid);
        }
    }

    void quiesce(size_t tid) {
        threads_[tid].local_epoch.store(EPOCH_INACTIVE, std::memory_order_seq_cst);
    }

    void retire_node(size_t tid, EpochNode* node) {
        if (!node) return;
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed) % 3;
        threads_[tid].retire_lists[cur_epoch].push_back(node);
    }

    void attempt_gc(size_t tid) {
        uint64_t current_g_epoch = global_epoch_.load(std::memory_order_relaxed);

        // Verify if all active threads have witnessed the current global epoch
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (!threads_[i].in_use.load(std::memory_order_relaxed)) continue;
            uint64_t t_epoch = threads_[i].local_epoch.load(std::memory_order_seq_cst);
            if (t_epoch != EPOCH_INACTIVE && t_epoch != current_g_epoch) {
                return; // Stalled: a thread is still in an older epoch
            }
        }

        // Advance global epoch
        uint64_t next_epoch = (current_g_epoch + 1);
        if (global_epoch_.compare_exchange_strong(current_g_epoch, next_epoch, 
                std::memory_order_seq_cst, std::memory_order_relaxed)) {
            // Free memory for safe epoch: (next_epoch + 1) % 3
            size_t safe_reclaim_epoch = (next_epoch + 1) % 3;
            auto& list = threads_[tid].retire_lists[safe_reclaim_epoch];
            for (auto* ptr : list) {
                delete ptr;
            }
            list.clear();
        }
    }

    uint64_t get_global_epoch() const {
        return global_epoch_.load(std::memory_order_acquire);
    }
};

class EpochGuard {
    EpochManager& mgr_;
    size_t tid_;
public:
    EpochGuard(EpochManager& mgr, size_t tid) : mgr_(mgr), tid_(tid) {
        mgr_.enter_epoch(tid_);
    }
    ~EpochGuard() {
        mgr_.exit_epoch(tid_);
    }
};
