### 2.3 Bw-Tree Delta Node Hierarchy & Indirection Mapping Table

```cpp
// ============================================================================
// 2.3 BW-TREE NODE HIERARCHY & DELTA TYPES
// ============================================================================

enum class NodeType : uint8_t {
    BASE_LEAF,
    BASE_INTERNAL,
    DELTA_INSERT,
    DELTA_DELETE,
    DELTA_SPLIT,
    DELTA_REMOVE
};

struct alignas(std::hardware_destructive_interference_size) BwTreeNode : public EpochNode {
    NodeType type;
    uint32_t chain_length{0};
    BwTreeNode* next{nullptr};

    explicit BwTreeNode(NodeType t, uint32_t len = 0, BwTreeNode* n = nullptr) 
        : type(t), chain_length(len), next(n) {}
};

struct KVPair {
    KeyType key;
    ValueType val;
    TxnTS commit_ts;
};

struct BaseLeafNode : public BwTreeNode {
    std::vector<KVPair> records; // Sorted by Key, then descending commit_ts

    BaseLeafNode() : BwTreeNode(NodeType.BASE_LEAF, 0, nullptr) {}
};

struct BaseInternalNode : public BwTreeNode {
    std::vector<KeyType> keys;
    std::vector<PageID> children;

    BaseInternalNode() : BwTreeNode(NodeType.BASE_INTERNAL, 0, nullptr) {}
};

struct InsertDeltaNode : public BwTreeNode {
    KeyType key;
    ValueType val;
    TxnTS commit_ts;

    InsertDeltaNode(KeyType k, ValueType v, TxnTS ts, uint32_t len, BwTreeNode* n)
        : BwTreeNode(NodeType.DELTA_INSERT, len, n), key(k), val(v), commit_ts(ts) {}
};

struct DeleteDeltaNode : public BwTreeNode {
    KeyType key;
    TxnTS commit_ts;

    DeleteDeltaNode(KeyType k, TxnTS ts, uint32_t len, BwTreeNode* n)
        : BwTreeNode(NodeType.DELTA_DELETE, len, n), key(k), commit_ts(ts) {}
};

struct SplitDeltaNode : public BwTreeNode {
    KeyType split_key;
    PageID right_sibling_pid;

    SplitDeltaNode(KeyType sk, PageID right_pid, uint32_t len, BwTreeNode* n)
        : BwTreeNode(NodeType.DELTA_SPLIT, len, n), split_key(sk), right_sibling_pid(right_pid) {}
};

// ============================================================================
// 2.4 INDIRECTION MAPPING TABLE
// ============================================================================

class MappingTable {
private:
    struct alignas(std::hardware_destructive_interference_size) Entry {
        std::atomic<BwTreeNode*> node_ptr{nullptr};
    };

    std::array<Entry, MAPPING_TABLE_CAPACITY> table_{};
    std::atomic<PageID> next_pid_{1}; // PID 0 reserved as invalid

public:
    MappingTable() = default;

    PageID allocate_page(BwTreeNode* initial_node) {
        PageID pid = next_pid_.fetch_add(1, std::memory_order_relaxed);
        if (pid >= MAPPING_TABLE_CAPACITY) {
            throw std::runtime_error("Mapping table exhausted capacity");
        }
        table_[pid].node_ptr.store(initial_node, std::memory_order_release);
        return pid;
    }

    BwTreeNode* get_node(PageID pid) const {
        assert(pid < MAPPING_TABLE_CAPACITY);
        return table_[pid].node_ptr.load(std::memory_order_acquire);
    }

    bool compare_and_swap(PageID pid, BwTreeNode* expected, BwTreeNode* desired) {
        assert(pid < MAPPING_TABLE_CAPACITY);
        return table_[pid].node_ptr.compare_exchange_strong(
            expected, desired,
            std::memory_order_release,  // On success: publish desired node
            std::memory_order_acquire   // On failure: reload expected node with fresh state
        );
    }
};
