### 2.4 Asynchronous `io_uring` Write-Ahead Logging (WAL) Subsystem

```cpp
// ============================================================================
// 2.5 ASYNC IO_URING WAL PIPELINE & GROUP COMMIT
// ============================================================================

enum class WalRecordType : uint8_t {
    INSERT = 1,
    DELETE = 2,
    TXN_COMMIT = 3,
    PAD_WRAP = 4
};

#pragma pack(push, 1)
struct WalRecordHeader {
    uint32_t total_size;
    WalRecordType type;
    TxnTS commit_ts;
    KeyType key;
    ValueType val;
    uint32_t checksum;
};
#pragma pack(pop)

class IoUringWal {
private:
    int wal_fd_{-1};
    struct io_uring ring_{};
    alignas(IO_BLOCK_SIZE) uint8_t* log_buffer_{nullptr};

    std::atomic<uint64_t> alloc_offset_{0};
    std::atomic<uint64_t> written_offset_{0};
    std::atomic<uint64_t> flushed_lsn_{0};

    std::atomic<bool> is_running_{true};
    std::thread bg_flush_thread_;

    static uint32_t compute_crc32(const uint8_t* data, size_t len) {
        uint32_t crc = 0xFFFFFFFF;
        for (size_t i = 0; i < len; ++i) {
            crc ^= data[i];
            for (int j = 0; j < 8; ++j) {
                crc = (crc >> 1) ^ (0xEDB88320 & (-(crc & 1)));
            }
        }
        return ~crc;
    }

public:
    IoUringWal(const std::string& path) {
        // Open file with O_DIRECT | O_RDWR | O_CREAT
        wal_fd_ = open(path.c_str(), O_DIRECT | O_RDWR | O_CREAT | O_TRUNC, 0644);
        if (wal_fd_ < 0) {
            throw std::system_error(errno, std::generic_category(), "Failed to open WAL file with O_DIRECT");
        }

        // Fallocate initial WAL disk space
        if (fallocate(wal_fd_, 0, 0, WAL_BUFFER_SIZE * 2) != 0) {
            throw std::system_error(errno, std::generic_category(), "Failed to fallocate WAL");
        }

        // Initialize io_uring
        struct io_uring_params params{};
        params.flags = IORING_SETUP_SQPOLL; // Kernel submission polling thread
        params.sq_thread_idle = 2000;       // 2ms idle timeout

        if (io_uring_queue_init_params(256, &ring_, &params) < 0) {
            // Fallback if SQPOLL is not permitted
            if (io_uring_queue_init(256, &ring_, 0) < 0) {
                throw std::runtime_error("Failed to initialize io_uring queue");
            }
        }

        // Allocate aligned circular buffer for O_DIRECT
        void* ptr = nullptr;
        if (posix_memalign(&ptr, IO_BLOCK_SIZE, WAL_BUFFER_SIZE) != 0) {
            throw std::bad_alloc();
        }
        log_buffer_ = static_cast<uint8_t*>(ptr);
        std::memset(log_buffer_, 0, WAL_BUFFER_SIZE);

        bg_flush_thread_ = std::thread(&IoUringWal::flusher_loop, this);
    }

    ~IoUringWal() {
        is_running_.store(false, std::memory_order_release);
        if (bg_flush_thread_.joinable()) {
            bg_flush_thread_.join();
        }
        io_uring_queue_exit(&ring_);
        if (wal_fd_ >= 0) close(wal_fd_);
        if (log_buffer_) free(log_buffer_);
    }

    uint64_t append_record(WalRecordType type, TxnTS ts, KeyType key, ValueType val) {
        uint32_t record_len = sizeof(WalRecordHeader);
        assert(record_len <= IO_BLOCK_SIZE);

        while (true) {
            uint64_t cur_alloc = alloc_offset_.load(std::memory_order_relaxed);
            uint64_t buf_pos = cur_alloc % WAL_BUFFER_SIZE;

            // Check if record fits before the end of the ring buffer
            if (buf_pos + record_len > WAL_BUFFER_SIZE) {
                // Pad to circular boundary
                uint32_t pad_size = WAL_BUFFER_SIZE - buf_pos;
                if (alloc_offset_.compare_exchange_weak(cur_alloc, cur_alloc + pad_size,
                        std::memory_order_acq_rel, std::memory_order_relaxed)) {
                    // Mark pad header
                    WalRecordHeader pad_hdr{};
                    pad_hdr.total_size = pad_size;
                    pad_hdr.type = WalRecordType::PAD_WRAP;
                    pad_hdr.checksum = 0;
                    std::memcpy(log_buffer_ + buf_pos, &pad_hdr, sizeof(WalRecordHeader));
                }
                continue; // Re-attempt allocation at offset 0
            }

            if (alloc_offset_.compare_exchange_weak(cur_alloc, cur_alloc + record_len,
                    std::memory_order_acq_rel, std::memory_order_relaxed)) {

                WalRecordHeader hdr;
                hdr.total_size = record_len;
                hdr.type = type;
                hdr.commit_ts = ts;
                hdr.key = key;
                hdr.val = val;
                hdr.checksum = compute_crc32(reinterpret_cast<const uint8_t*>(&hdr), 
                                             sizeof(WalRecordHeader) - sizeof(uint32_t));

                std::memcpy(log_buffer_ + buf_pos, &hdr, sizeof(WalRecordHeader));
                return cur_alloc + record_len; // LSN
            }
        }
    }

    void wait_flushed(uint64_t target_lsn) {
        while (flushed_lsn_.load(std::memory_order_acquire) < target_lsn) {
            std::this_thread::yield();
        }
    }

private:
    void flusher_loop() {
        while (is_running_.load(std::memory_order_relaxed)) {
            uint64_t cur_alloc = alloc_offset_.load(std::memory_order_acquire);
            uint64_t cur_written = written_offset_.load(std::memory_order_relaxed);

            if (cur_alloc > cur_written) {
                size_t start_pos = cur_written % WAL_BUFFER_SIZE;
                size_t bytes_to_write = cur_alloc - cur_written;

                // Truncate to ring buffer boundary if needed
                if (start_pos + bytes_to_write > WAL_BUFFER_SIZE) {
                    bytes_to_write = WAL_BUFFER_SIZE - start_pos;
                }

                // Align write size up to IO_BLOCK_SIZE for direct I/O
                size_t aligned_bytes = (bytes_to_write + IO_BLOCK_SIZE - 1) & ~(IO_BLOCK_SIZE - 1);

                // Prepare io_uring write SQE
                struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
                while (!sqe) {
                    io_uring_submit(&ring_);
                    sqe = io_uring_get_sqe(&ring_);
                }

                off_t file_offset = static_cast<off_t>(cur_written);
                io_uring_prep_write(sqe, wal_fd_, log_buffer_ + start_pos, aligned_bytes, file_offset);
                sqe->user_data = cur_written + bytes_to_write;

                io_uring_submit(&ring_);

                // Harvest CQE
                struct io_uring_cqe* cqe = nullptr;
                int ret = io_uring_wait_cqe(&ring_, &cqe);
                if (ret == 0 && cqe) {
                    if (cqe->res >= 0) {
                        uint64_t completed_lsn = cqe->user_data;
                        written_offset_.store(completed_lsn, std::memory_order_relaxed);
                        flushed_lsn_.store(completed_lsn, std::memory_order_release);
                    }
                    io_uring_cqe_seen(&ring_, cqe);
                }
            } else {
                std::this_thread::sleep_for(std::chrono::microseconds(100));
            }
        }
    }
};
