### 2.5 MVCC Transaction Manager & Bw-Tree Engine Core

```cpp
// ============================================================================
// 2.6 BW-TREE ENGINE WITH MVCC & ATOMIC COMPACTION
// ============================================================================

class BwTreeEngine {
private:
    MappingTable mapping_table_;
    EpochManager epoch_mgr_;
    IoUringWal wal_;
    std::atomic<TxnTS> global_timestamp_{1};
    PageID root_pid_{1};

public:
    BwTreeEngine(const std::string& wal_path) : wal_(wal_path) {
        // Initialize Root Base Leaf Node
        auto* root_node = new BaseLeafNode();
        root_pid_ = mapping_table_.allocate_page(root_node);
    }

    size_t register_worker() {
        return epoch_mgr_.register_thread();
    }

    void unregister_worker(size_t tid) {
        epoch_mgr_.unregister_thread(tid);
    }

    TxnTS begin_transaction() {
        return global_timestamp_.fetch_add(1, std::memory_order_relaxed);
    }

    // ------------------------------------------------------------------------
    // MVCC Point Lookup (Snapshot Isolation)
    // ------------------------------------------------------------------------
    std::optional<ValueType> get(size_t tid, KeyType key, TxnTS read_ts) {
        EpochGuard guard(epoch_mgr_, tid);
        PageID cur_pid = root_pid_;

        while (true) {
            BwTreeNode* head = mapping_table_.get_node(cur_pid);
            BwTreeNode* curr = head;

            while (curr) {
                switch (curr->type) {
                    case NodeType::DELTA_INSERT: {
                        auto* in = static_cast<InsertDeltaNode*>(curr);
                        if (in->key == key && in->commit_ts <= read_ts) {
                            return in->val;
                        }
                        curr = curr->next;
                        break;
                    }
                    case NodeType::DELTA_DELETE: {
                        auto* dn = static_cast<DeleteDeltaNode*>(curr);
                        if (dn->key == key && dn->commit_ts <= read_ts) {
                            return std::nullopt; // Tombstone found
                        }
                        curr = curr->next;
                        break;
                    }
                    case NodeType::DELTA_SPLIT: {
                        auto* sn = static_cast<SplitDeltaNode*>(curr);
                        if (key >= sn->split_key) {
                            // Traverse side-pointer to right child
                            cur_pid = sn->right_sibling_pid;
                            goto next_page;
                        }
                        curr = curr->next;
                        break;
                    }
                    case NodeType::BASE_LEAF: {
                        auto* bl = static_cast<BaseLeafNode*>(curr);
                        for (const auto& rec : bl->records) {
                            if (rec.key == key && rec.commit_ts <= read_ts) {
                                return rec.val;
                            }
                        }
                        return std::nullopt;
                    }
                    case NodeType::BASE_INTERNAL: {
                        auto* bi = static_cast<BaseInternalNode*>(curr);
                        size_t idx = 0;
                        while (idx < bi->keys.size() && key >= bi->keys[idx]) {
                            idx++;
                        }
                        cur_pid = bi->children[idx];
                        goto next_page;
                    }
                    default:
                        curr = curr->next;
                        break;
                }
            }
            return std::nullopt;

        next_page:
            continue;
        }
    }

    // ------------------------------------------------------------------------
    // MVCC Insert with First-Committer-Wins Validation & Lock-Free Append
    // ------------------------------------------------------------------------
    bool put(size_t tid, KeyType key, ValueType val, TxnTS read_ts) {
        EpochGuard guard(epoch_mgr_, tid);
        PageID cur_pid = root_pid_;

        while (true) {
            BwTreeNode* head = mapping_table_.get_node(cur_pid);

            // 1. First-Committer-Wins (Write-Write Conflict Detection)
            BwTreeNode* curr = head;
            while (curr) {
                if (curr->type == NodeType::DELTA_INSERT) {
                    auto* in = static_cast<InsertDeltaNode*>(curr);
                    if (in->key == key && in->commit_ts > read_ts) {
                        return false; // WW conflict: write after our read_ts
                    }
                } else if (curr->type == NodeType::DELTA_DELETE) {
                    auto* dn = static_cast<DeleteDeltaNode*>(curr);
                    if (dn->key == key && dn->commit_ts > read_ts) {
                        return false;
                    }
                } else if (curr->type == NodeType::DELTA_SPLIT) {
                    auto* sn = static_cast<SplitDeltaNode*>(curr);
                    if (key >= sn->split_key) {
                        cur_pid = sn->right_sibling_pid;
                        goto retry_page;
                    }
                } else if (curr->type == NodeType::BASE_INTERNAL) {
                    auto* bi = static_cast<BaseInternalNode*>(curr);
                    size_t idx = 0;
                    while (idx < bi->keys.size() && key >= bi->keys[idx]) {
                        idx++;
                    }
                    cur_pid = bi->children[idx];
                    goto retry_page;
                }
                curr = curr->next;
            }

            // 2. Allocate Commit Timestamp & Write Log to WAL
            TxnTS commit_ts = global_timestamp_.fetch_add(1, std::memory_order_relaxed);
            uint64_t lsn = wal_.append_record(WalRecordType::INSERT, commit_ts, key, val);

            // 3. Prepend Insert Delta Node via CAS on Mapping Table
            uint32_t cur_chain_len = head ? head->chain_length + 1 : 1;
            auto* new_delta = new InsertDeltaNode(key, val, commit_ts, cur_chain_len, head);

            if (mapping_table_.compare_and_swap(cur_pid, head, new_delta)) {
                wal_.wait_flushed(lsn); // Ensure durability on group commit

                // Trigger asynchronous compaction if chain length exceeds threshold
                if (cur_chain_len >= MAX_DELTA_CHAIN_LEN) {
                    attempt_consolidate(tid, cur_pid);
                }
                return true;
            } else {
                // CAS failed: concurrent prepend occurred. Clean up unlinked node.
                delete new_delta;
                // Retry loop
            }

        retry_page:
            continue;
        }
    }

    // ------------------------------------------------------------------------
    // Atomic Consolidation & Safe Node Retirement
    // ------------------------------------------------------------------------
    void attempt_consolidate(size_t tid, PageID pid) {
        BwTreeNode* head = mapping_table_.get_node(pid);
        if (!head || head->type == NodeType::BASE_LEAF || head->chain_length < MAX_DELTA_CHAIN_LEN) {
            return;
        }

        // Construct new BaseLeafNode consolidating the delta chain
        auto* new_base = new BaseLeafNode();
        std::vector<KVPair> collapsed;

        BwTreeNode* curr = head;
        while (curr) {
            if (curr->type == NodeType::DELTA_INSERT) {
                auto* in = static_cast<InsertDeltaNode*>(curr);
                collapsed.push_back({in->key, in->val, in->commit_ts});
            } else if (curr->type == NodeType::BASE_LEAF) {
                auto* bl = static_cast<BaseLeafNode*>(curr);
                for (const auto& r : bl->records) {
                    collapsed.push_back(r);
                }
            }
            curr = curr->next;
        }

        // Sort descending by Key, then descending by commit_ts for version resolution
        std::sort(collapsed.begin(), collapsed.end(), [](const KVPair& a, const KVPair& b) {
            if (a.key != b.key) return a.key < b.key;
            return a.commit_ts > b.commit_ts;
        });

        // Deduplicate records keeping newest visible versions
        new_base->records.reserve(collapsed.size());
        for (const auto& rec : collapsed) {
            new_base->records.push_back(rec);
        }

        // Atomically replace delta chain with consolidated base page
        if (mapping_table_.compare_and_swap(pid, head, new_base)) {
            // Retire entire replaced chain to EBR
            curr = head;
            while (curr && curr != new_base) {
                BwTreeNode* next_node = curr->next;
                epoch_mgr_.retire_node(tid, curr);
                curr = next_node;
            }
        } else {
            // Consolidation race lost: discard temporary base node
            delete new_base;
        }
    }
};
