### 2.6 Multi-Threaded Verification Benchmark

```cpp
// ============================================================================
// 2.7 VERIFICATION HARNESS
// ============================================================================

int main() {
    std::cout << "=== Bw-Tree with EBR and io_uring WAL Initializing ===" << std::endl;
    std::string wal_file = "/tmp/bwtree_test.wal";

    std::unique_ptr<BwTreeEngine> engine;
    try {
        engine = std::make_unique<BwTreeEngine>(wal_file);
    } catch (const std::exception& e) {
        std::cerr << "Engine Initialization Exception: " << e.what() << std::endl;
        return 1;
    }

    constexpr size_t NUM_WRITERS = 4;
    constexpr size_t OPS_PER_THREAD = 10000;
    std::vector<std::thread> workers;
    std::atomic<size_t> successful_puts{0};
    std::atomic<size_t> successful_gets{0};

    auto start_time = std::chrono::high_resolution_clock::now();

    // Spawn concurrent writers
    for (size_t t = 0; t < NUM_WRITERS; ++t) {
        workers.emplace_back([&, t]() {
            size_t tid = engine->register_worker();
            for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
                KeyType key = (t * OPS_PER_THREAD + i) % 1000;
                ValueType val = t * 1000000 + i;
                TxnTS read_ts = engine->begin_transaction();

                if (engine->put(tid, key, val, read_ts)) {
                    successful_puts.fetch_add(1, std::memory_order_relaxed);
                }

                auto res = engine->get(tid, key, read_ts + 1);
                if (res.has_value()) {
                    successful_gets.fetch_add(1, std::memory_order_relaxed);
                }
            }
            engine->unregister_worker(tid);
        });
    }

    for (auto& w : workers) {
        w.join();
    }

    auto end_time = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> diff = end_time - start_time;

    std::cout << "Execution Finished in " << diff.count() << " seconds." << std::endl;
    std::cout << "Total Successful Puts: " << successful_puts.load() << std::endl;
    std::cout << "Total Successful Gets: " << successful_gets.load() << std::endl;
    std::cout << "Throughput: " << (successful_puts.load() + successful_gets.load()) / diff.count() << " ops/sec" << std::endl;

    unlink(wal_file.c_str());
    return 0;
}
