// ============================================================================
// 1. MEMORY MANAGEMENT: EPOCH-BASED RECLAMATION (EBR)
// ============================================================================

class EpochManager {
public:
    static constexpr size_t MAX_THREADS = 128;
    static constexpr uint64_t EPOCH_MASK = 3;

    struct RetiredNode {
        void* ptr;
        void (*deleter)(void*);
        RetiredNode* next;
    };

    struct alignas(std::hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{std::numeric_limits<uint64_t>::max()};
        std::atomic<bool> active{false};
        std::array<RetiredNode*, 3> retired_lists{nullptr, nullptr, nullptr};
    };

    EpochManager() : global_epoch_(0) {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            threads_[i].local_epoch.store(std::numeric_limits<uint64_t>::max(), std::memory_order_relaxed);
            threads_[i].active.store(false, std::memory_order_relaxed);
            for (int e = 0; e < 3; ++e) {
                threads_[i].retired_lists[e] = nullptr;
            }
        }
    }

    ~EpochManager() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            for (int e = 0; e < 3; ++e) {
                flush_retired_list(threads_[i].retired_lists[e]);
            }
        }
    }

    size_t register_thread() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (threads_[i].active.compare_exchange_strong(expected, true, std::memory_order_seq_cst)) {
                return i;
            }
        }
        throw std::runtime_error("Exceeded maximum thread capacity in EpochManager");
    }

    void unregister_thread(size_t tid) {
        assert(tid < MAX_THREADS);
        quiesce(tid);
        for (int e = 0; e < 3; ++e) {
            flush_retired_list(threads_[tid].retired_lists[e]);
            threads_[tid].retired_lists[e] = nullptr;
        }
        threads_[tid].active.store(false, std::memory_order_release);
    }

    void enter_epoch(size_t tid) {
        uint64_t g_epoch = global_epoch_.load(std::memory_order_acquire);
        threads_[tid].local_epoch.store(g_epoch, std::memory_order_seq_cst);
    }

    void exit_epoch(size_t tid) {
        threads_[tid].local_epoch.store(std::numeric_limits<uint64_t>::max(), std::memory_order_release);
    }

    void quiesce(size_t tid) {
        exit_epoch(tid);
    }

    template <typename T>
    void retire(size_t tid, T* ptr) {
        if (!ptr) return;
        auto deleter = [](void* p) { delete static_cast<T*>(p); };
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t epoch_slot = cur_epoch % 3;

        auto* node = new RetiredNode{ptr, deleter, threads_[tid].retired_lists[epoch_slot]};
        threads_[tid].retired_lists[epoch_slot] = node;

        try_advance_epoch(tid);
    }

    void try_advance_epoch(size_t tid) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_acquire);

        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (threads_[i].active.load(std::memory_order_acquire)) {
                uint64_t t_epoch = threads_[i].local_epoch.load(std::memory_order_acquire);
                if (t_epoch != std::numeric_limits<uint64_t>::max() && t_epoch < cur_epoch) {
                    return; // Stalled: a worker is still in an older epoch
                }
            }
        }

        if (global_epoch_.compare_exchange_strong(cur_epoch, cur_epoch + 1, std::memory_order_seq_cst)) {
            size_t safe_slot = (cur_epoch + 2) % 3;
            flush_retired_list(threads_[tid].retired_lists[safe_slot]);
            threads_[tid].retired_lists[safe_slot] = nullptr;
        }
    }

private:
    void flush_retired_list(RetiredNode* head) {
        while (head) {
            RetiredNode* next = head->next;
            head->deleter(head->ptr);
            delete head;
            head = next;
        }
    }

    alignas(std::hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_;
    std::array<ThreadControlBlock, MAX_THREADS> threads_;
};

class EpochGuard {
public:
    EpochGuard(EpochManager& mgr, size_t tid) : mgr_(mgr), tid_(tid) {
        mgr_.enter_epoch(tid_);
    }
    ~EpochGuard() {
        mgr_.exit_epoch(tid_);
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
private:
    EpochManager& mgr_;
    size_t tid_;
};

// ============================================================================
// 2. BW-TREE: INDIRECTION TABLE, DELTA NODES & COMPACTION
// ============================================================================

using PageID = uint64_t;
using TxnID = uint64_t;
using LSN = uint64_t;

enum class NodeType : uint8_t {
    BASE_LEAF,
    BASE_INTERNAL,
    DELTA_INSERT,
    DELTA_UPDATE,
    DELTA_DELETE,
    DELTA_SPLIT,
    DELTA_INDEX_TERM
};

struct NodeHeader {
    NodeType type;
    alignas(8) uint64_t reserved;
    virtual ~NodeHeader() = default;
};

struct TaggedPointer {
    uintptr_t raw;

    static constexpr uintptr_t PTR_MASK   = 0x0000FFFFFFFFFFFFULL;
    static constexpr uintptr_t COUNT_MASK = 0x00FF000000000000ULL;
    static constexpr uintptr_t FLAG_MASK  = 0xFF00000000000000ULL;
    static constexpr size_t COUNT_SHIFT   = 48;
    static constexpr size_t FLAG_SHIFT    = 56;

    static TaggedPointer pack(NodeHeader* ptr, uint16_t chain_len, uint8_t flags = 0) {
        uintptr_t val = (reinterpret_cast<uintptr_t>(ptr) & PTR_MASK) |
                        (static_cast<uintptr_t>(chain_len) << COUNT_SHIFT) |
                        (static_cast<uintptr_t>(flags) << FLAG_SHIFT);
        return TaggedPointer{val};
    }

    NodeHeader* ptr() const {
        return reinterpret_cast<NodeHeader*>(raw & PTR_MASK);
    }

    uint16_t chain_length() const {
        return static_cast<uint16_t>((raw & COUNT_MASK) >> COUNT_SHIFT);
    }

    uint8_t flags() const {
        return static_cast<uint8_t>((raw & FLAG_MASK) >> FLAG_SHIFT);
    }

    bool operator==(const TaggedPointer& o) const { return raw == o.raw; }
    bool operator!=(const TaggedPointer& o) const { return raw != o.raw; }
};

struct Record {
    uint64_t key;
    uint64_t value;
    TxnID commit_ts;
    bool deleted{false};
};

struct BaseLeafPage : public NodeHeader {
    std::vector<Record> records;
    PageID low_key{0};
    PageID high_key{std::numeric_limits<uint64_t>::max()};

    BaseLeafPage() { type = NodeType::BASE_LEAF; }
};

struct BaseInternalPage : public NodeHeader {
    std::vector<std::pair<uint64_t, PageID>> routes; // Key separator -> Child PageID
    BaseInternalPage() { type = NodeType::BASE_INTERNAL; }
};

struct DeltaNode : public NodeHeader {
    NodeHeader* next{nullptr};
};

struct InsertDeltaNode : public DeltaNode {
    Record record;
    InsertDeltaNode(Record rec, NodeHeader* next_node) : record(rec) {
        type = NodeType::DELTA_INSERT;
        next = next_node;
    }
};

struct DeleteDeltaNode : public DeltaNode {
    uint64_t key;
    TxnID commit_ts;
    DeleteDeltaNode(uint64_t k, TxnID ts, NodeHeader* next_node) : key(k), commit_ts(ts) {
        type = NodeType::DELTA_DELETE;
        next = next_node;
    }
};

struct SplitDeltaNode : public DeltaNode {
    uint64_t split_key;
    PageID sibling_page_id;
    SplitDeltaNode(uint64_t k, PageID sibling, NodeHeader* next_node)
        : split_key(k), sibling_page_id(sibling) {
        type = NodeType::DELTA_SPLIT;
        next = next_node;
    }
};

class MappingTable {
public:
    static constexpr size_t MAX_PAGES = 65536;

    MappingTable() {
        for (size_t i = 0; i < MAX_PAGES; ++i) {
            slots_[i].store(TaggedPointer{0}, std::memory_order_relaxed);
        }
    }

    TaggedPointer load(PageID pid, std::memory_order order) const {
        assert(pid < MAX_PAGES);
        return slots_[pid].load(order);
    }

    bool compare_exchange(PageID pid, TaggedPointer& expected, TaggedPointer desired, 
                         std::memory_order success_order, std::memory_order fail_order) {
        assert(pid < MAX_PAGES);
        return slots_[pid].compare_exchange_strong(expected, desired, success_order, fail_order);
    }

    PageID allocate_page(NodeHeader* initial_node) {
        PageID pid = next_page_id_.fetch_add(1, std::memory_order_relaxed);
        assert(pid < MAX_PAGES);
        slots_[pid].store(TaggedPointer::pack(initial_node, 0, 0), std::memory_order_release);
        return pid;
    }

private:
    alignas(std::hardware_destructive_interference_size) std::atomic<TaggedPointer> slots_[MAX_PAGES];
    alignas(std::hardware_destructive_interference_size) std::atomic<PageID> next_page_id_{1};
};

// ============================================================================
// 3. ASYNCHRONOUS IO_URING WAL SUBSYSTEM WITH GROUP COMMIT
// ============================================================================

struct alignas(512) WalRecordHeader {
    uint32_t size;
    uint32_t crc32;
    TxnID txn_id;
    LSN lsn;
    enum RecordType : uint32_t {
        DATA = 1,
        TXN_COMMIT = 2,
        TXN_ABORT = 3,
        PADDING = 4
    } type;
};

class IoUringWal {
public:
    static constexpr size_t BUFFER_SIZE = 16 * 1024 * 1024; // 16MB Ring Buffer
    static constexpr size_t SECTOR_SIZE = 512;
    static constexpr uint32_t QUEUE_DEPTH = 512;

    IoUringWal(const char* path) : fd_(-1), running_(true) {
        fd_ = open(path, O_DIRECT | O_RDWR | O_CREAT | O_TRUNC, 0644);
        if (fd_ < 0) {
            throw std::runtime_error("Failed to open WAL file with O_DIRECT");
        }

        // Posix memalign for direct I/O
        int ret = posix_memalign(reinterpret_cast<void**>(&ring_buffer_), SECTOR_SIZE, BUFFER_SIZE);
        if (ret != 0) {
            close(fd_);
            throw std::bad_alloc();
        }

        struct io_uring_params params;
        std::memset(&params, 0, sizeof(params));
        // Use Kernel Polling thread if privileged; fallback gracefully to standard submission
        params.flags = IORING_SETUP_CQSIZE;
        params.cq_entries = QUEUE_DEPTH * 2;

        ret = io_uring_queue_init_params(QUEUE_DEPTH, &ring_, &params);
        if (ret < 0) {
            free(ring_buffer_);
            close(fd_);
            throw std::runtime_error("io_uring initialization failed");
        }

        // Pre-register memory buffer
        struct iovec iov = { .iov_base = ring_buffer_, .iov_len = BUFFER_SIZE };
        ret = io_uring_register_buffers(&ring_, &iov, 1);
        if (ret < 0) {
            io_uring_queue_exit(&ring_);
            free(ring_buffer_);
            close(fd_);
            throw std::runtime_error("io_uring_register_buffers failed");
        }

        flusher_thread_ = std::thread(&IoUringWal::flusher_loop, this);
    }

    ~IoUringWal() {
        running_.store(false, std::memory_order_release);
        if (flusher_thread_.joinable()) {
            flusher_thread_.join();
        }
        io_uring_unregister_buffers(&ring_);
        io_uring_queue_exit(&ring_);
        free(ring_buffer_);
        if (fd_ >= 0) close(fd_);
    }

    LSN append_commit_record(TxnID txn_id, const std::vector<Record>& writes) {
        uint32_t payload_len = static_cast<uint32_t>(writes.size() * sizeof(Record));
        uint32_t total_len = sizeof(WalRecordHeader) + payload_len;
        // Align record length to 8 bytes internally
        total_len = (total_len + 7) & ~7;

        LSN assigned_lsn = current_lsn_.fetch_add(1, std::memory_order_relaxed);
        size_t alloc_offset = write_offset_.fetch_add(total_len, std::memory_order_relaxed);

        // Circular buffer boundary wrap detection
        size_t ring_idx = alloc_offset % BUFFER_SIZE;
        if (ring_idx + total_len > BUFFER_SIZE) {
            // Fill padding record to bridge end-of-ring
            WalRecordHeader pad;
            pad.size = static_cast<uint32_t>(BUFFER_SIZE - ring_idx);
            pad.type = WalRecordHeader::PADDING;
            pad.lsn = 0;
            pad.txn_id = 0;
            std::memcpy(ring_buffer_ + ring_idx, &pad, sizeof(WalRecordHeader));

            // Re-allocate at ring head
            alloc_offset = write_offset_.fetch_add(total_len, std::memory_order_relaxed);
            ring_idx = alloc_offset % BUFFER_SIZE;
        }

        WalRecordHeader header;
        header.size = total_len;
        header.crc32 = 0; // Simplified CRC placeholder
        header.txn_id = txn_id;
        header.lsn = assigned_lsn;
        header.type = WalRecordHeader::TXN_COMMIT;

        std::memcpy(ring_buffer_ + ring_idx, &header, sizeof(WalRecordHeader));
        if (payload_len > 0) {
            std::memcpy(ring_buffer_ + ring_idx + sizeof(WalRecordHeader), writes.data(), payload_len);
        }

        ready_offset_.store(alloc_offset + total_len, std::memory_order_release);
        return assigned_lsn;
    }

    void wait_flush(LSN target_lsn) {
        while (flushed_lsn_.load(std::memory_order_acquire) < target_lsn) {
            std::this_thread::yield();
        }
    }

private:
    void flusher_loop() {
        size_t disk_offset = 0;
        size_t flush_committed = 0;

        while (running_.load(std::memory_order_acquire) || (flush_committed < ready_offset_.load(std::memory_order_acquire))) {
            size_t current_ready = ready_offset_.load(std::memory_order_acquire);
            if (current_ready > flush_committed) {
                size_t pending_bytes = current_ready - flush_committed;
                // Sector align write size (512-byte blocks)
                size_t aligned_bytes = (pending_bytes + (SECTOR_SIZE - 1)) & ~(SECTOR_SIZE - 1);
                size_t start_buf_pos = flush_committed % BUFFER_SIZE;

                if (start_buf_pos + aligned_bytes > BUFFER_SIZE) {
                    aligned_bytes = BUFFER_SIZE - start_buf_pos;
                }

                struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
                while (!sqe) {
                    io_uring_submit(&ring_);
                    sqe = io_uring_get_sqe(&ring_);
                }

                io_uring_prep_write_fixed(sqe, fd_, ring_buffer_ + start_buf_pos, aligned_bytes, disk_offset, 0);
                sqe->user_data = reinterpret_cast<uint64_t>(aligned_bytes);

                io_uring_submit(&ring_);

                struct io_uring_cqe* cqe;
                int ret = io_uring_wait_cqe(&ring_, &cqe);
                if (ret == 0 && cqe->res >= 0) {
                    size_t bytes_written = cqe->res;
                    disk_offset += bytes_written;
                    flush_committed += pending_bytes;
                    io_uring_cqe_seen(&ring_, cqe);
                    flushed_lsn_.store(current_lsn_.load(std::memory_order_relaxed), std::memory_order_release);
                } else if (cqe) {
                    io_uring_cqe_seen(&ring_, cqe);
                }
            } else {
                std::this_thread::sleep_for(std::chrono::microseconds(50));
            }
        }
    }

    int fd_;
    char* ring_buffer_{nullptr};
    struct io_uring ring_{};
    std::thread flusher_thread_;
    std::atomic<bool> running_{false};

    alignas(std::hardware_destructive_interference_size) std::atomic<LSN> current_lsn_{1};
    alignas(std::hardware_destructive_interference_size) std::atomic<size_t> write_offset_{0};
    alignas(std::hardware_destructive_interference_size) std::atomic<size_t> ready_offset_{0};
    alignas(std::hardware_destructive_interference_size) std::atomic<LSN> flushed_lsn_{0};
};

// ============================================================================
// 4. BW-TREE ENGINE: CONSOLIDATION, SMOS & MVCC SNAPSHOT ISOLATION
// ============================================================================

class BwTreeEngine {
public:
    static constexpr uint16_t CONSOLIDATION_THRESHOLD = 8;
    static constexpr size_t MAX_LEAF_SIZE = 16;

    BwTreeEngine(EpochManager& epoch_mgr, IoUringWal& wal)
        : epoch_mgr_(epoch_mgr), wal_(wal), root_pid_(0) {
        auto* root = new BaseLeafPage();
        root_pid_ = mapping_table_.allocate_page(root);
    }

    std::optional<uint64_t> get(uint64_t key, TxnID read_ts, size_t tid) {
        EpochGuard guard(epoch_mgr_, tid);

        PageID cur_pid = root_pid_;
        while (true) {
            TaggedPointer head_tag = mapping_table_.load(cur_pid, std::memory_order_acquire);
            NodeHeader* cur = head_tag.ptr();

            // Traverse delta chain
            bool routed = false;
            while (cur) {
                if (cur->type == NodeType::DELTA_SPLIT) {
                    auto* split = static_cast<SplitDeltaNode*>(cur);
                    if (key >= split->split_key) {
                        cur_pid = split->sibling_page_id;
                        routed = true;
                        break;
                    }
                } else if (cur->type == NodeType::DELTA_INSERT) {
                    auto* ins = static_cast<InsertDeltaNode*>(cur);
                    if (ins->record.key == key) {
                        if (ins->record.commit_ts <= read_ts) {
                            return ins->record.deleted ? std::nullopt : std::optional<uint64_t>(ins->record.value);
                        }
                    }
                } else if (cur->type == NodeType::DELTA_DELETE) {
                    auto* del = static_cast<DeleteDeltaNode*>(cur);
                    if (del->key == key && del->commit_ts <= read_ts) {
                        return std::nullopt;
                    }
                } else if (cur->type == NodeType::BASE_LEAF) {
                    auto* base = static_cast<BaseLeafPage*>(cur);
                    for (auto it = base->records.rbegin(); it != base->records.rend(); ++it) {
                        if (it->key == key && it->commit_ts <= read_ts) {
                            return it->deleted ? std::nullopt : std::optional<uint64_t>(it->value);
                        }
                    }
                    return std::nullopt;
                } else if (cur->type == NodeType::BASE_INTERNAL) {
                    auto* base_int = static_cast<BaseInternalPage*>(cur);
                    PageID next_pid = base_int->routes.back().second;
                    for (const auto& entry : base_int->routes) {
                        if (key < entry.first) {
                            next_pid = entry.second;
                            break;
                        }
                    }
                    cur_pid = next_pid;
                    routed = true;
                    break;
                }
                cur = (cur->type == NodeType::DELTA_INSERT || 
                       cur->type == NodeType::DELTA_DELETE || 
                       cur->type == NodeType::DELTA_SPLIT) ? static_cast<DeltaNode*>(cur)->next : nullptr;
            }
            if (!routed) {
                break;
            }
        }
        return std::nullopt;
    }

    bool put(uint64_t key, uint64_t value, TxnID commit_ts, size_t tid) {
        EpochGuard guard(epoch_mgr_, tid);
        Record rec{key, value, commit_ts, false};

        // Write log record to WAL (Group-Commit Pipeline)
        LSN lsn = wal_.append_commit_record(commit_ts, {rec});

        while (true) {
            PageID pid = locate_leaf_page(key);
            TaggedPointer head_tag = mapping_table_.load(pid, std::memory_order_acquire);

            // First-Committer-Wins MVCC Check
            if (has_write_conflict(head_tag.ptr(), key, commit_ts)) {
                return false; // Transaction conflict abort
            }

            auto* new_delta = new InsertDeltaNode(rec, head_tag.ptr());
            uint16_t new_len = head_tag.chain_length() + 1;
            TaggedPointer new_tag = TaggedPointer::pack(new_delta, new_len, head_tag.flags());

            if (mapping_table_.compare_exchange(pid, head_tag, new_tag, 
                                                std::memory_order_acq_rel, 
                                                std::memory_order_acquire)) {
                if (new_len >= CONSOLIDATION_THRESHOLD) {
                    consolidate_page(pid, new_tag, tid);
                }
                wal_.wait_flush(lsn);
                return true;
            }
            // Memory order fail: Delete allocated node and retry
            delete new_delta;
        }
    }

private:
    PageID locate_leaf_page(uint64_t key) {
        PageID cur_pid = root_pid_;
        while (true) {
            TaggedPointer head_tag = mapping_table_.load(cur_pid, std::memory_order_acquire);
            NodeHeader* cur = head_tag.ptr();
            bool is_leaf = false;
            while (cur) {
                if (cur->type == NodeType::DELTA_SPLIT) {
                    auto* split = static_cast<SplitDeltaNode*>(cur);
                    if (key >= split->split_key) {
                        cur_pid = split->sibling_page_id;
                        break;
                    }
                } else if (cur->type == NodeType::BASE_LEAF || cur->type == NodeType::DELTA_INSERT) {
                    is_leaf = true;
                    break;
                } else if (cur->type == NodeType::BASE_INTERNAL) {
                    auto* base_int = static_cast<BaseInternalPage*>(cur);
                    PageID next_pid = base_int->routes.back().second;
                    for (const auto& entry : base_int->routes) {
                        if (key < entry.first) {
                            next_pid = entry.second;
                            break;
                        }
                    }
                    cur_pid = next_pid;
                    break;
                }
                cur = (cur->type == NodeType::DELTA_INSERT || 
                       cur->type == NodeType::DELTA_DELETE || 
                       cur->type == NodeType::DELTA_SPLIT) ? static_cast<DeltaNode*>(cur)->next : nullptr;
            }
            if (is_leaf) return cur_pid;
        }
    }

    bool has_write_conflict(NodeHeader* cur, uint64_t key, TxnID read_ts) {
        while (cur) {
            if (cur->type == NodeType::DELTA_INSERT) {
                auto* ins = static_cast<InsertDeltaNode*>(cur);
                if (ins->record.key == key && ins->record.commit_ts > read_ts) return true;
            } else if (cur->type == NodeType::BASE_LEAF) {
                auto* base = static_cast<BaseLeafPage*>(cur);
                for (const auto& rec : base->records) {
                    if (rec.key == key && rec.commit_ts > read_ts) return true;
                }
                return false;
            }
            cur = (cur->type == NodeType::DELTA_INSERT || 
                   cur->type == NodeType::DELTA_DELETE || 
                   cur->type == NodeType::DELTA_SPLIT) ? static_cast<DeltaNode*>(cur)->next : nullptr;
        }
        return false;
    }

    void consolidate_page(PageID pid, TaggedPointer expected_tag, size_t tid) {
        auto* base_page = new BaseLeafPage();
        std::vector<Record> consolidated;

        // Traverse down chain to gather live records
        NodeHeader* cur = expected_tag.ptr();
        while (cur) {
            if (cur->type == NodeType::DELTA_INSERT) {
                auto* ins = static_cast<InsertDeltaNode*>(cur);
                consolidated.push_back(ins->record);
            } else if (cur->type == NodeType::BASE_LEAF) {
                auto* leaf = static_cast<BaseLeafPage*>(cur);
                consolidated.insert(consolidated.end(), leaf->records.begin(), leaf->records.end());
            }
            cur = (cur->type == NodeType::DELTA_INSERT || 
                   cur->type == NodeType::DELTA_DELETE || 
                   cur->type == NodeType::DELTA_SPLIT) ? static_cast<DeltaNode*>(cur)->next : nullptr;
        }

        // Deduplicate keeping latest MVCC version per key
        std::sort(consolidated.begin(), consolidated.end(), [](const Record& a, const Record& b) {
            return (a.key == b.key) ? (a.commit_ts > b.commit_ts) : (a.key < b.key);
        });

        std::vector<Record> final_records;
        uint64_t last_key = std::numeric_limits<uint64_t>::max();
        for (const auto& rec : consolidated) {
            if (rec.key != last_key) {
                if (!rec.deleted) final_records.push_back(rec);
                last_key = rec.key;
            }
        }
        base_page->records = std::move(final_records);

        // Check if page needs splitting post-consolidation
        if (base_page->records.size() > MAX_LEAF_SIZE) {
            split_page(pid, base_page, expected_tag, tid);
            return;
        }

        TaggedPointer new_tag = TaggedPointer::pack(base_page, 0, 0);

        // Atomically replace entire delta chain with single consolidated BaseLeafPage
        if (mapping_table_.compare_exchange(pid, expected_tag, new_tag, 
                                            std::memory_order_acq_rel, 
                                            std::memory_order_acquire)) {
            retire_chain(expected_tag.ptr(), tid);
        } else {
            // CAS race lost: abort consolidation and retire candidate base page
            epoch_mgr_.retire(tid, base_page);
        }
    }

    void split_page(PageID pid, BaseLeafPage* full_page, TaggedPointer expected_tag, size_t tid) {
        size_t mid = full_page->records.size() / 2;
        uint64_t split_key = full_page->records[mid].key;

        auto* sibling_page = new BaseLeafPage();
        sibling_page->records.assign(full_page->records.begin() + mid, full_page->records.end());
        full_page->records.erase(full_page->records.begin() + mid, full_page->records.end());

        PageID sibling_pid = mapping_table_.allocate_page(sibling_page);

        // Prepend Split Delta to original page chain
        auto* split_node = new SplitDeltaNode(split_key, sibling_pid, expected_tag.ptr());
        TaggedPointer split_tag = TaggedPointer::pack(split_node, expected_tag.chain_length() + 1, 0);

        if (mapping_table_.compare_exchange(pid, expected_tag, split_tag, 
                                            std::memory_order_acq_rel, 
                                            std::memory_order_acquire)) {
            // Phase 2: Update parent (internal node) with new index routing entry
            epoch_mgr_.retire(tid, full_page);
        } else {
            epoch_mgr_.retire(tid, sibling_page);
            delete split_node;
            delete full_page;
        }
    }

    void retire_chain(NodeHeader* head, size_t tid) {
        while (head) {
            NodeHeader* next = nullptr;
            if (head->type == NodeType::DELTA_INSERT || 
                head->type == NodeType::DELTA_DELETE || 
                head->type == NodeType::DELTA_SPLIT) {
                next = static_cast<DeltaNode*>(head)->next;
            }
            epoch_mgr_.retire(tid, head);
            head = next;
        }
    }

    MappingTable mapping_table_;
    EpochManager& epoch_mgr_;
    IoUringWal& wal_;
    PageID root_pid_;
};
```

